window.EH_DATA.TXT = {
"stehender-ruderzug-mit-seilzug":{"v":"Hänge den Seilzug in mittlerer Position ein. Falte das Griffband zweimal und führ es durch die Schlaufe des Seilzugs.","a":"Stell dich in einen leichten Ausfallschritt und greif die Griffschlaufen mit beiden Händen. Wähle die Position so, dass bei gestreckten Armen bereits Zug auf dem Seilzug spürbar ist.","f":"Beginne die Bewegung im Obergriff. Zieh die Hände kontrolliert an die Rippen und dreh sie dabei langsam in den Hammergriff. Zieh die Schulterblätter nach hinten.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Ruderzug seitlich stehend","ruderzug-seitlich-stehend"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"]]},
"221-shrugs-mit-griff-am-horn":{"v":"Fixiere die Schlitten auf Hüfthöhe, sodass die Hornspitzen ungefähr in der Mitte deiner Oberschenkel liegen. Dreh beide Schlitten leicht nach innen und stell dich mit dem Rücken zum Gerät.","a":"Stell dich stabil und parallel hin. Greife mit jeder Hand ein Horn und halte die Arme gestreckt. Bei aufrechtem Stand spürst du bereits Zug auf dem Horn. Halte den Rücken gerade und den Bauch angespannt.","f":"Zieh beide Schultern über die Nackenmuskulatur gleichzeitig nach oben und leicht nach hinten. Halte die Position kurz und kehre dann langsam in die Ausgangsposition zurück. Die Arme bleiben während der gesamten Übung gestreckt.","t":"Stell dir vor, du möchtest deine Schultern so weit wie möglich hinter die Ohren schieben – ruhig und kontrolliert.","vt":"Führe die Bewegung alternativ alternierend mit der einen und dann mit der anderen Seite aus. So trainierst du beide Körperhälften gleichmässig.","va":[["Shrugs alternierend mit Griff am Horn","220-shrugs-alternierend-mit-griff-am-horn"],["Nackenheben hinten","nackenheben-hinten"]]},
"ueberkopf-trizepsdruecken-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Falte das Griffband zweimal und führ es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, beuge den Oberkörper leicht nach vorne und halte ihn stabil. Zieh die Schultern nach hinten und strecke die Brust heraus. Greif die Schlaufe mit einer Hand und führe sie hinter den Kopf, sodass der Ellenbogen nach oben zeigt.","f":"Drück den Unterarm langsam nach oben, bis er fast vollständig gestreckt ist. Der Oberarm bleibt dabei senkrecht und kippt nicht zur Seite. Senk den Unterarm danach langsam wieder in die Ausgangsposition.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"latzug-in-den-nacken":{"v":"Positioniere den Schlitten zur Vorbereitung auf Kopfhöhe. Achte darauf, dass du die Griffstange mit gestreckten Armen gerade noch greifen kannst.","a":"Zum Start stellst du dich in einen sicheren Ausfallschritt. Anschliessend umfasst du die Griffstange mit breitem, festem Griff. Neige jetzt deinen Oberkörper leicht nach vorne – so bist du perfekt für diese Kraftübung vorbereitet.","f":"Ziehe die Griffstange langsam nach unten, bis sie leicht deinen Nacken berührt. Achte dabei auf eine gleichmässige Bewegung.","t":"Lehne deinen Kopf ein kleines Stück nach vorne, so kannst du die Griffstange sauber in den Nacken ziehen. Achte darauf, dass deine Körperspannung durchgehend erhalten bleibt.","vt":"Du kannst diese Übung auch sitzend und mit unterschiedlicher Griffbreite durchführen. Weitere Alternativen zu dieser Kraftübung findest du weiter unten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"klimmzug-auf-die-brust":{"v":"Du legst die Griffstange ein und installierst den Blocker. Stelle die Höhe so ein, dass du die Griffstange mit vollständig gestreckten Armen gerade noch erreichen kannst.","a":"Du greifst die Stange mit breitem Obergriff und lässt deinen Körper locker hängen. Ob du die Beine ausgestreckt hältst oder leicht anwinkelst, bleibt ganz dir überlassen.","f":"Du ziehst dich ohne Schwung kontrolliert nach oben, bis dein Kinn über der Stange schwebt. Dann lässt du dich langsam und kontrolliert wieder herab in die Ausgangsposition. Achte darauf, deine Arme am Ende leicht angewinkelt zu belassen.","t":"Führe die Übung langsam und kontrolliert aus – kein Schwung, volle Muskelarbeit!","vt":"Du kannst bei dieser Übung mit unterschiedlichen Griffbreiten und Griffarten (Ober- und Untergriff) variieren. Dadurch setzt du unterschiedliche Trainingsreize.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Klimmzug mit Griffstange","228-klimmzug-mit-griffstange"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"115-latzug-zur-brust-sitzend":{"v":"Fixiere den Schlitten so, dass er in sitzender Position auf Kopfhöhe liegt. Die Griffstange ist bei gestreckten Armen gerade noch erreichbar.","a":"Setz dich auf einen Ball oder Stuhl unter die Griffstange. Greif die Stange im Obergriff und lehne den Oberkörper leicht nach hinten.","f":"Zieh die Griffstange langsam und gleichmässig bis auf die Brust. Senke sie danach kontrolliert wieder in die Ausgangsposition.","t":"Achte darauf, die Ellbogen aktiv nach hinten zu führen und dabei die Körperspannung dauerhaft aufrechtzuerhalten.","vt":"Du kannst die Übung variieren, indem du die Griffbreite anpasst und/oder im Untergriff trainierst.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"schulterheben-vorne":{"v":"Fixiere den Schlitten in der Mitte der Säule und lege die Griffstange ein.","a":"Stelle dich mit Blick zum Gerät nah ans Horn. Passe die Höhe so an, dass du die Griffstange bei gestrecktem Oberkörper gerade noch erreichen kannst. Greife die Stange mit stabilem Stand und richte dich auf. Halte die Arme gestreckt und spüre die Dehnung in der Nackenmuskulatur.","f":"Ziehe die Schultern über die Nackenmuskulatur nach oben und gleichzeitig nach hinten. Halte die Position kurz und führe die Bewegung dann langsam zurück in die Ausgangsstellung. Achte darauf, dass dein Kopf still bleibt und die Arme stets gestreckt bleiben.","t":"Bewege die Schultern aktiv nach oben, als würdest du sie hinter die Ohren ziehen.","va":[["Shrugs alternierend mit Griff am Horn","220-shrugs-alternierend-mit-griff-am-horn"],["Shrugs mit Griff am Horn","221-shrugs-mit-griff-am-horn"],["Nackenheben hinten","nackenheben-hinten"]]},
"wadenheben-sitzend":{"v":"Führe die Griffstange ein und fixiere den Schlitten so, dass er leicht oberhalb deiner Knie positioniert ist. Platziere eine stabile Erhöhung (z. B. ein Brett oder ein dickes Buch) direkt unter der Griffstange.","a":"Setze dich auf einen Ball oder Stuhl vor die Griffstange. Halte deinen Oberkörper aufrecht und stelle deine Beine hüftbreit nebeneinander. Platziere nun die Vorderfüsse auf der Erhöhung. Die Schlittenhöhe sollte so eingestellt sein, dass die Griffstange bei gesenkten Fersen bereits Kontakt mit deinen Oberschenkeln hat. Greife die Griffstange mit beiden Händen in einem engem Griff.","f":"Hebe deine Fersen langsam vom Boden ab und drücke sie so weit wie möglich nach oben. Achte darauf, die Bewegung kontrolliert auszuführen. Senke anschliessend deine Fersen langsam wieder in die Ausgangsposition ab.","va":[["Wadenheben mit Griff am Horn","219-wadenheben-mit-griff-am-horn"],["Stehendes Wadenheben","stehendes-wadenheben"],["Wadenheben stehend exzentrisch","wadenheben-stehend-exzentrisch"]]},
"kniebeugen":{"v":"Du ziehst die Griffstange durch die Schlaufe und positionierst den Schlitten so, dass die Stange in der tiefen Hocke knapp oberhalb deiner Brust steht.","a":"Du stellst dich hüftbreit hin, blickst zur Wand und positionierst die Griffstange etwas unterhalb deiner Schultern an der Brust. Deine Ellenbogen richtest du nach vorne aus und kreuzt die Hände über dem Horn.","f":"Nun drückst du dich mit kraftvollem Einsatz deiner Beine nach oben, während dein Schwerpunkt sich leicht nach vorne verschiebt. Dein Rücken bleibt dabei gerade und angespannt.","t":"Nutze einen tiefen Hocker (ca. 30 cm Höhe), um dich bequem in die sitzende Startposition unter die Griffstange zu bringen.","vt":"Die Fussposition kann etwas nach vorne oder zurück verschoben werden.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"kreuzheben-mit-griffstange-deadlift":{"v":"Positioniere den Schlitten so, dass sich die Griffstange mittig etwa auf Schienbeinhöhe befindet.","a":"Stelle dich hinter die Griffstange mit hüftbreitem Stand und in einer stabilen Hockposition. Greife die Stange im breiten Wechselgriff und blicke etwa 45 Grad Richtung Boden. Achte darauf, dass dein Rücken jederzeit voll gespannt und gerade bleibt (ein leichtes Hohlkreuz) und dein Kopf eine Verlängerung der Wirbelsäule bildet.","f":"Richte dich kontrolliert auf, lasse dabei deine Arme vollständig gestreckt. Die Kraft stammt aus den Beinen und der unteren Rückenmuskulatur. In der Endposition sind deine Schultern nach hinten gezogen, aber nicht hochgezogen.","t":"Konzentriere dich darauf, die Arbeit vollständig aus den Beinen und dem Rücken zu initiieren. Vermeide, deine Schultern oder Arme aktiv nach oben zu ziehen . Der Deadlift soll ein Zusammenspiel grosser Muskelgruppen bleiben und keine isolierte Armleistung.","vt":"Alternative Ausführungsvarianten mit unterschiedlichen Griffen und Ständen siehe unten.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"aussenrotation-seitlich-mit-griffband":{"v":"Fixiere den Schlitten auf Ellenbogenhöhe in horizontaler Position und bringe das Griffband an.","a":"Nimm einen seitlichen, stabilen Stand ein, mit Blick zur Wand. Die Hand, die weiter vom Horn entfernt ist, hält beide Griffschlaufen. Dein Oberarm liegt eng am Oberkörper an, während der Unterarm in seiner Ausgangsposition vor dem Bauch positioniert ist.","f":"Drehe den Unterarm nun langsam nach aussen. Dein Ellenbogen bleibt dabei in Position. Kehre dann langsam zur Ausgangsposition zurück. Halte dabei stets die Spannung aufrecht.","va":[["Innenrotation mit Seilzug","innenrotation-mit-seilzug"],["Aussenrotation mit Seilzug","aussenrotation-mit-seilzug"],["Innenrotation seitlich mit Griffband","innenrotation-seitlich-mit-griffband"]]},
"schulterdruecken-sitzend":{"v":"Fixiere den Schlitten in der Mitte der Säule und lege die Griffstange an.","a":"Setze dich auf einem Ball oder Stuhl vor die Griffstange und greife diese weit aussen. Wähle die Höhe so, dass sich die Griffstange auf Höhe des Schlüsselbeins befindet.","f":"Drücke jetzt die Griffstange gleichmässig nach oben, bis die Arme gestreckt sind. Bewege die Arme anschliessend wieder alngsam zurück in die Ausgangsposition.","t":"Achte darauf, dass dein Körper stabil und aufrecht bleibt. Vermeide ein Hohlkreuz, halte die Rumpfspannung dauerhaft und die Schultern unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"],["Schulterdrücken mit engem Griff","schulterdruecken-mit-engem-griff"]]},
"uebungen-fuer-den-trizeps":{"v":"Stelle das Trainingsgewicht so ein, dass du die Übung sauber und ohne Schwung ausführen kannst. Befestige anschliessend das Griffband und lege die Griffstange in beide Griffschlazen ein. Achte darauf, dass alles sicher eingehängt ist. Stelle nun die Höhe der Griffstange leicht under der Brust ein.","a":"Nimm eine aufrechte Körperhaltung ein, die Füsse stehen hüftbreit und geben dir damit einen stabilen Halt. Greife die Stange im Obergriff, also mit den Handflächen nach unten, und beuge deine Ellbogen so, dass die Unterarme fast waagerecht nach vorne zeigen. Dein Oberkörper darf leicht nach vorne geneigt sein, während Rücken und Kopf in einer neutralen Position bleiben. Spanne zusätzlich Bauch- und Gesässmuskeln leicht an, um den Rumpf stabil zu halten.","f":"Strecke die Unterarme kontrolliert nach unten, bis deine Arme fast vollständig durchgestreckt sind. Die Ellbogen bleiben dabei eng am Körper fixiert und bewegen sich nicht nach aussen oder hinten. Achte darauf, dass die Kraft allein aus dem Trizeps kommt und du keinen Schwung aus Schultern oder Rücken holst. Halte die Endposition für einen kurzen Moment, bevor du die Stange langsam und kontrolliert wieder nach oben führst, ohne die Spannung vollständig zu verlieren.","t":"Konzentriere dich bei jeder Wiederholung bewusst auf die Anspannung im Trizeps. Atme während des Drückens nach unten aus und beim Zurückführen wieder ein. Achte ausserdem daarauf, dass du nahe am Gerät stehst, damit die Ellenbogen bei der Ausführung nicht nach vorne ziehen.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"abduktion-am-seilzug":{"v":"Hänge den Seilzug in unterer Position ein.","a":"Stell dich seitlich nahe ans Gerät und positioniere den abgewandten Fuss in der Schlaufe. Das Standbein bleibt leicht gebeugt.","f":"Bewege das aktive Bein langsam und kontrolliert so weit wie möglich nach aussen, ohne die Hüfte zu drehen. Anschliessend das Bein wieder langsam nach innen führen, ohne das Gewicht abzusetzen.","t":"Achte darauf, die Übung langsam und sauber auszuführen – vermeide Schwungbewegungen.","va":[["Kickbacks am Seilzug","kickbacks-am-seilzug"],["Ausfallschritte","ausfallschritte"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"209-brustdruecken-stehend-mit-griffstange":{"v":"Stelle die Griffstange auf Oberbrusthöhe ein. Achte darauf, dass sie hoch genug sitzt, damit du die Bewegung hauptsächlich aus der Brustmuskulatur steuerst und nicht durch ein zu stark nach vorne geneigtes Oberkörpergewicht.","a":"Stelle dich im Stemmschritt stabil hin. Lehn den Oberkörper leicht nach vorne und bring die Brust nahe an die Griffstange. Greife die Stange im breiten Obergriff, halte den Rücken gerade und spanne den Bauch an.","f":"Drücke die Griffstange gleichmässig nach unten, bis die Arme gestreckt sind. Am untersten Punkt führe die Stange kontrolliert und langsam zurück in die Ausgangsposition.","t":"Achte darauf, dicht an der Griffstange zu stehen und den Rumpf stabil zu halten. Im Stemmschritt führst du die Bewegung bewusst über die Brustmuskeln aus.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Dips mit Gewicht","dips-mit-gewicht"],["Butterfly","butterfly"],["Dips mit Griffband","dips-mit-griffband"]]},
"trizepsdruecken":{"v":"Lege die Griffstange ein und fixieren den Schlitten so, dass die Griffstange in liegender Position knapp über der Brust liegt.","a":"Lege dich auf Brusthöhe unter die Griffstange und fasse sie schulterbreit. Beuge die Ellenbogen, sodass sie nah am Oberkörper bleiben. Winkele die Beine an und stelle die Füsse fest auf den Boden.","f":"Drücke nun die Griffstange gleichmässig nach oben bis deine Arme fast gestreckt sind. Anschliessend bewegst du dich langsam in die Ausgangsposition zurück.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"innenrotation-seitlich-mit-griffband":{"v":"Fixiere den Schlitten auf Ellenbogenhöhe in horizontaler Position und bringe das Griffband an.","a":"Nimm einen seitlichen, stabilen Stand ein, mit Blick zur Wand. Die Hand, die sich näher am Horn befindet, hält beide Griffschlaufen. Dein Oberarm liegt am Oberkörper an, der Unterarm ist im 90° Winkel nach vorne gestreckt.","f":"Ziehe den Unterarm langsam in Richtung deines Bauchs. Dein Ellenbogen bleibt in Position. Bewege den Unterarm anschliessend langsam wieder zurück in die Ausgangsposition. Halte dabei stets die Spannung aufrecht.","t":"Halte deinen Oberkörper stabil und unbewegt. Führe die Übung konsequent in beide Richtungen aus. um deine Muskulatur gleichmässig zu trainieren.","va":[["Innenrotation mit Seilzug","innenrotation-mit-seilzug"]]},
"trizepsuebung-mit-griffstange-im-untergriff":{"v":"Fixiere den Schlitten im oberen Bereich. Befestige das Griffband und lege die Griffstange in beide Schlaufen ein. Wähle die Höhe so, dass die Stange auf Brusthöhe liegt.","a":"Greife die Griffstange im Untergriff, während du einen stabilen Stemmschritt einnimmst. Stehe dabei nah an der Stange, lehne den Oberkörper leicht nach vorne, halte den Rücken gerade und spanne die Bauchmuskeln an.","f":"Drücke die Griffstange nach unten, deine Ellbogen bleiben dabei unverändert an der gleichen Position. Es bewegen sich ausschliesslich deine Unterarme.","t":"Stelle dich bei der Übungsausführung dicht an deine Kraftstation bzw. das Horn.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"]]},
"ruderzug-seitlich-stehend":{"v":"Stelle deinen Schlitten auf Bauchhöhe mit leichter Neigung fast horizontal ein. Führe anschliessend ein Ende deines Griffbandes durch die Hornschlaufe und greife beide Griffbandschlaufen mit festem Griff. Das Griffband sollte jetzt sicher am Horn befestigt sein und du bist startklar.","a":"Positioniere dich zum Beginn der Übung seitlich zu deiner Kraftstation in einem stabilen Stemmschritt. Halte deinen Oberkörper aufrecht und spanne den Rumpf an, sodass dein Körper stabil und kontrolliert bleibt. Die Arme sind in der Ausgangsposition ganz gestreckt und die Schulterblätter hinten unten platziert.","f":"Ziehe deine Ellenbogen langsam und eng am Körper entlang nach hinten, während du die Hände parallel zu den Rippen führst. Achte darauf, deine Schulterblätter bewusst nach hinten zu ziehen und die Bewegung ohne Schwung aus der Rückenmuskulatur einzuleiten.","t":"Halte deinen Rücken während der gesamten Bewegung gerade und konzentriere dich darauf, aus dem Rücken und nicht aus den Armen zu ziehen.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"]]},
"schulterheben-hinten":{"v":"Fixiere den Schlitten im unteren Bereich. Bringe anschliessen das Griffband an und lege die Griffstange in beide Griffschlaufen ein.","a":"Positioniere dich hüftbreit und mit deinem Rücken zum Gerät. Greife nun die Griffstange hinter dem Gesäss. Achte darauf, dass die Schlittenhöhe so eingestellt ist, dass in stehender Position mit gestreckten Armen bereits etwas Zug auf dem Horn ist.","f":"Ziehe nun die Schultern langsam zusammen und führe die Arme dabei am Körper entlang nach oben. Anschliessend deine Schultern und Arme wieder kontrolliert absenken.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"]]},
"bizepscurls-mit-griffstange-und-seilzug":{"v":"Hänge den Seilzug in unterer Position ein und lege die Griffstange ein.","a":"Stell dich hüftbreit hin und halte den Oberkörper aufrecht und stabil. Zieh die Schultern nach hinten und strecke die Brust nach vorne. Greife die Griffstange mit beiden Händen schulterbreit im Untergriff. Spanne den ganzen Körper an.","f":"Führe die Griffstange gleichmässig nach oben bis zur maximalen Höhe. Senke sie danach langsam und kontrolliert wieder in die Ausgangsposition.","t":"Achte darauf, deine Ellbogen dicht am Körper zu halten. Der Oberkörper, sowie Schultern und Oberarme, bleiben unbewegt – die Arbeit machen allein die Ellbogen.","va":[["Bizepscurls stehend","bizepscurls"],["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Hammer Curls","hammer-curls"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"crossover-crunch-am-seilzug":{"v":"Hänge den Seilzug in unserer Position ein.","a":"Leg dich mit den Füssen zum Gerät auf den Rücken und führ einen Fuss in die Schlaufe des Seilzugs. Wähle die Position auf dem Boden so, dass bei gestrecktem Bein bereits leichter Zug auf dem Horn spürbar ist.","f":"Leg einen Arm im rechten Winkel zum Oberkörper auf den Boden und führ die andere Hand an den Kopf. Spanne die Rumpfmuskulatur an und führ den Ellenbogen und das diagonale Knie zur Mitte zusammen.","va":[["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"],["Rumpfbeugen seitlich","rumpfbeugen-seitlich"]]},
"ueberkopf-kniebeugen-overhead-squats":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass die Stange direkt unterhalb deines Schlüsselbeins liegt.","a":"Stell dich mit dem Rücken an die Griffstange und hebe sie leicht mit den Schultern an. Greife die Stange mit beiden Händen weit aussen, strecke anschliessend die Arme. Richte deinen Blick nach vorne und verlagere das Körpergewicht gleichmäßig auf die gesamte Fusssohle.","f":"Gehe mit gestreckten Armen in die Hocke, bis das Hüftgelenk unterhalb der Knie liegt. Drücke dich dann wieder nach oben, bis die Beine fast gestreckt sind. Halte während der gesamten Bewegung den Rücken in einer „Bogenspannung“ und spanne den Bauch an. Beim Absenken führst du das Gesäss möglichst weit nach hinten.","t":"Achte darauf, dass die Knie nicht nach innen einknicken und immer über den Füssen bleiben. Strecke die Beine in der Endposition nicht vollständig durch, um die Muskeln unter Spannung zu halten und die Knie zu schonen.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Frontkniebeugen","kniebeugen"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"]]},
"einbeinige-beinpresse":{"v":"Fixiere den Schlitten so, dass du dich bequem mit gebeugtem Bein darunter legen kannst.","a":"Leg dich flach auf den Boden, Rücken vollständig aufliegend – ohne Hohlkreuz. Positioniere ein Bein angewinkelt auf dem Horn, wobei der Fussballen die Spitze berührt. Das andere Bein ist ebenfalls gebeugt, die Fusssohle ruht flach auf dem Boden. Deine Arme liegen entspannt und ausgestreckt seitlich neben dir.","f":"Bewege dein Bein mit Druck aus dem Oberschenkel langsam und gleichmässig nach oben, bis es fast gestreckt ist. Streck am Ende den Fuss aktiv durch. Danach senk dein Bein kontrolliert ab – kurz vor dem Anschlag bist du wieder in der Ausgangsposition. Achte darauf, dein Knie während der gesamten Bewegung stabil und ausgerichtet zu halten.","t":"Diese einbeinige Übung zeigt dir genau, wo in deiner Beinmuskulatur Schwächen oder Mobilitätsbegrenzungen liegen. Dies äussert sich durch ruckelnde Bewegungen beim ablassen. Mit der Zeit wird sich die Bewegung kontrollierter, flüssiger und stärker anfühlen.","va":[["Einbeinige rückwärtige Beinpresse","einbeinige-rueckwaertige-beinpresse"],["Beinpresse","beinpresse"]]},
"222-fliegende-mit-seilzug-von-unten":{"v":"Fixiere beide Seilzüge in der unteren Position und drehe die Schlitten leicht nach innen.","a":"Stell dich im stabilen Stemmschritt mit dem Rücken zum Gerät. Greife mit jeder Hand eine Seilzugschlaufe und passe deine Position so an, dass bei nach hinten gestreckten Armen bereits Zug auf dem Seilzug ist. Dein Oberkörper ist aktiv nach vorne geneigt und bildet mit dem hinteren Bein eine Linie.","f":"Führe deine Hände in einer Bogenform von hinten unten nach vorne oben zur Mitte. Die Hände treffen sich in der Mitte. Anschliessend kehrst du kontrolliert in die Ausgangsposition zurück.","va":[["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Butterfly","butterfly"]]},
"einbeinige-rueckwaertige-beinpresse":{"v":"Positioniere den Schlitten so, dass dein bewegendes Bein gerade bequem angelegt werden kann.","a":"Begebe dich in den Vierfüsslerstand, stütze dich auf deinen Unterarmen ab und platziere den Vorderfuss deines zu trainierenden Beins in einer Flexposition am Horn. Deine Ellbogen liegen direkt unter den Schultergelenken, und dein Blick ist nach unten gerichtet. Achte darauf, während der gesamten Übung eine vollständig gespannte Körperhaltung zu bewahren.","f":"Drücke dein Bein langsam gegen das Gewicht nach oben, bis dein Knie die Höhe der Hüfte erreicht. Anschliessend führst du das Bein kontrolliert zurück in die Ausgangsposition – allerdings ohne das Ende des Bewegungswegs vollständig zu erreichen (bis kurz vor dem Anschlag).","t":"Am besten übst du diese Bewegung zunächst ohne Geräte, um die Technik zu verinnerlichen. Für mehr Sicherheit kannst du zusätzliche die Griffstange nutzen, damit dein Fuss nicht abrutscht. Um ein besseres Gefühl und eine bessere Kontrolle zu haben, kann die Übung ohne Schuhe ausgeführt werden.","va":[["Einbeinige Beinpresse","einbeinige-beinpresse"],["Beinpresse","beinpresse"]]},
"liegestuetze-mit-griffband":{"v":"Stelle die höchste Kraftstufe ein und fixiere den Schlitten ganz oben. Befestige anschliessend beide Griffbänder mit Hilfe des Karabinerhakens.","a":"Halte deine Arme gestreckt in den Schlaufen, dein Oberkörper ist nach vorne gelehnt mit totaler Körperspannung.","f":"Beuge nun deine Arme und führe deine Brust zwischen den Händen nach vorne. Gehe danach langsam und kontrolliert wieder in die Ausgangsposition zurück.","va":[["Liegestütze mit einem Bein im Griffband","liegestuetze-mit-einem-bein-im-griffband"],["Liegestütze mit Griffband und Griffstange","liegestuetze-mit-griffband-und-griffstange"]]},
"217-alternierende-dips-stehend":{"v":"Fixiere die Schlitten auf Hüfthöhe.","a":"Stell dich im stabilen Stemmschritt hin. Greife mit jeder Hand ein Horn, sodass dein Oberkörper leicht nach vorne geneigt ist. Halte den Rücken gerade, spanne den Bauch an und richte den Blick zum Boden. Gehe in der Ausgangsposition schon leicht in die Dehnung deiner Brust.","f":"Drücke eine Hand nach unten, bis der Arm vollständig gestreckt ist. Führe denselben Arm danach wieder zurück in die Ausgangsposition und wiederhole die Bewegung abwechselnd. Achte darauf, deinen Rumpf zu stabilisieren, damit dein Oberkörper möglichst ruhig bleibt.","t":"Achte darauf, den Oberkörper leicht nach vorne zu neigen und den Rumpf stabil zu halten. Im Stemmschritt bleiben die Arme eng am Oberkörper, damit der Trizeps optimal arbeitet.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Dips","214-dips"],["Dips mit Gewicht","dips-mit-gewicht"],["Dips mit Griffband","dips-mit-griffband"]]},
"schulterdruecken-mit-engem-griff":{"v":"Setze die Griffstange ein und fixiere den Schlitten so, dass sich die Stange ungefähr auf Höhe deines Schlüsselbeins befindet.","a":"Stell dich mit festem, schulterbreitem Stand und geradem Rücken vor die Griffstange. Dein Blick bleibt nach vorne gerichtet. Greife die Stange in Schulterbreite.","f":"Drücke die Griffstange gleichmässig nach oben, bis deine Arme vollständig gestreckt sind. Senke sie danach kontrolliert zurück in die Ausgangsposition. Bevor die Stange den unteren Anschlag erreicht, leitest du die nächste Wiederholung ein.","t":"Achte darauf, die Übung mit aufrechter und stabiler Körperhaltung auszuführen. Vermeide ein Hohlkreuz, halte die Rumpfspannung konstant und lass deine Schultern unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"]]},
"beinbeuger-mit-griffband":{"v":"Stelle die höchste Kraftstufe ein und fixiere den Schlitten in der Mitte der Säule. Bringe nun an Griffband am Horn an.","a":"Lege dich auf den Rücken und führe je einen Fuss in eine Schlaufe ein.","f":"Hebe mit gestreckten Beinen das Becken vom Boden ab. Ziehe anschliessen mit angespanntem Rumpf die Fersen in Richtung Gesäss und schiebe das Becken weter nach oben.","va":[["Beinbeuger liegend","beinbeuger-liegend"]]},
"226-schulterrotatoren-alternierend-am-seilzug":{"v":"Hänge beide Seilzüge in der mittleren Position ein.","a":"Stelle dich mit aufrechtem Oberkörper und parallel stehenden Füssen vor das Gerät. Greife die Schlaufen im Obergriff und winkle deine Arme auf Schulterhöhe an. Deine Fäuste sollten nun exakt auf die jeweilige Säule der Kraftstation ausgerichtet sein.","f":"Führe deine Faust in einer runden Bewegung nach hinten und oben. Am Ende der Bewegung sollte sie etwa auf Höhe deines Kopfes sein. Halte den Oberarm dabei so stabil wie möglich und bewege nur den Unterarm über die Schulter, um die Rotation gezielt auszuführen.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"]]},
"210-schulterdruecken-am-horn-alternierend":{"v":"Fixiere den Schlitten so, dass sich die Enden der Hörner auf Höhe deiner Oberbrust befinden.","a":"Stell dich fest und parallel hin, halte den Rücken gerade. Greife die Hörner jeweils mit einer Hand am Ende.","f":"Drücke die Hörner abwechselnd nach oben, bis deine Arme gestreckt sind. Führe sie anschliessend langsam zurück. Bevor du den unteren Anschlag erreichst, drückst du wieder nach oben.","t":"Achte während der gesamten Übung auf eine aufrechte und gerade Körperhaltung. Halte deine Rumpfmuskeln kontinuierlich aktiv, vermeide ein Hohlkreuz und behalte deine Schultern unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"],["Schulterdrücken mit engem Griff","schulterdruecken-mit-engem-griff"]]},
"ausfallschritte":{"v":"Fixiere den Schlitten so, dass das Horn ungefähr auf Schienbeinhöhe positioniert ist. Diese Einstellung sorgt dafür, dass du in der Übung eine ergonomisch korrekte Haltung einnehmen kannst.","a":"Stehe seitlich neben dem Gerät in einem weiten Ausfallschritt. Fasse das Horn mit einer Hand und achte darauf, dass dein Rücken gerade bleibt.","f":"Drücke dich kraftvoll aus dem vorderen Bein nach oben, bis es fast vollständig gestreckt ist. Halte deinen Rumpf dabei angespannt und deinen Rücken gerade, um die maximale Aktivierung der Zielmuskeln zu gewährleisten.","t":"Führe die Übung auf beiden Seiten durch. Je weiter du deinen Ausfallschritt wählst, desto stärker arbeitet die Gesässmuskulatur – und desto weniger wird überwiegend der Quadrizeps belastet.","va":[["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"beinpresse":{"v":"Du fixierst den Schlitten so, dass du dich mit maximal angewinkelten Beinen bequem unter die Griffstange legen kannst.","a":"Du liegst auf dem Rücken, so dass dein Gesäss direkt unter der Griffstange liegt. Deine Arme liegen entspannt neben dem Körper auf dem Boden. Deine Füsse platzierst du hüftbreit auf der Griffstange – deine Oberschenkel berühren dabei deinen Bauch.","f":"Jetzt drückst du die Griffstange mit gleichmässigem Druck über deine Fussballen nach oben, bis deine Knie fast gestreckt sind. Wichtig: Halte dein Gesäss während der gesamten Bewegung angespannt.","va":[["Adduktion am Seilzug","adduktion-am-seilzug"],["Beinstrecker am Seilzug","beinstrecker-am-seilzug"],["Abduktion am Seilzug","abduktion-am-seilzug"],["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Stehendes Wadenheben","stehendes-wadenheben"],["Ausfallschritte","ausfallschritte"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Einbeinige Beinpresse","einbeinige-beinpresse"],["Einbeinige rückwärtige Beinpresse","einbeinige-rueckwaertige-beinpresse"]]},
"haengender-ruderzug-mit-angewinkelten-beinen":{"v":"Stelle die höchste Kraftstufe ein und bringe dein Griffband an deiner Kraftstation an.","a":"Halte die Arme gestreckt aber angespannt - lasse sie nicht durchhängen. Halte dabei stets die Spannung im Rücken.","f":"Führe nun eine natürliche Zugbewegung aus und ziehe die Ellbogen im Endpunkt hinten zusammen. Dein Körper bleibt dabei bis zum Kniegelenk in einer geraden Linie.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"]]},
"negativ-bankdruecken-mit-angehobenen-beinen":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Griffstange in liegender Position knapp über deiner Brust befindet.","a":"Lege dich auf den Rücken, greife die Griffstange an den Enden und positioniere sie auf Brusthöhe. Die Ellenbogen sind gebeugt und befinden sich auf Schulterhöhe. Deine Beine sind im 90-Grad-Winkel nach oben angewinkelt.","f":"Drücke die Griffstange gleichmässig nach oben, bis deine Arme fast gestreckt sind. Senke sie anschliessend langsam wieder in die Ausgangsposition ab.","t":"Um optimal in die Ausgangsposition zu gelangen, kann der Kolben über die Gewichtsstufen herausbewegt werden, sodass sich das Horn leicht nach oben verschieben lässt. Das Gewicht erst einstellen, wenn du dich in der liegenden Position befindest.","vt":"Spiele mit der Griffbreite: Aussen an der Griffstange ist es einfacher, bei engerem Griff wird das Training anspruchsvoller.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"]]},
"hueftheben":{"v":"Du legst die Griffstange ein und fixierst den Schlitten im unteren Bereich.","a":"Du setzt dich mit dem Blick zum Gerät auf den Boden und stützt dich auf deinen Händen ab. Deine Füsse stehen flach auf dem Boden, die Beine bilden einen rechten Winkel. Die Griffstange liegt direkt über dem Übergang zum Oberschenkel.","f":"Du drückst dein Gesäss nach oben, bis dein Oberkörper und deine Oberschenkel in einer Linie sind. Halte die Spannung und senke dich kontrolliert wieder ab.","vt":"Du kannst deine Hände entweder seitlich oder mit den Fingern in Richtung der Füsse positionieren.","va":[["Hüftheben seitlich","hueftheben-seitlich"]]},
"rudern-vorgebeugt-mit-untergriff":{"v":"Du legst die Griffstange ein und fixierst den Schlitten so, dass sich die Griffstange in etwa auf Schienbeinhöhe befindet.","a":"Du nimmst eine leichte Hocke ein und beugst deinen Oberkörper leicht nach vorn. Fasse die Stange mit schulterbreitem Untergriff, halte deinen Rücken unter voller Spannung (mit leichtem Hohlkreuz), das Gesäss nach hinten, die Brust leicht vorgeschoben. Dein Blick ruht auf dem Boden.","f":"Führe die Griffstange kontrolliert zur Hüfte. Deine Oberarme bleiben dabei dicht am Oberkörper. Danach lässt du die Stange langsam und kontrolliert wieder zurück in die Ausgangsposition gleiten.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"011-trizepsuebung-mit-griffband-kniend":{"v":"Führe das Griffband durch die Schlaufe und fixiere den Schlitten so, dass die Bandenden in kniender Haltung etwa auf Brusthöhe hängen.","a":"Knie dich mit einem stabilen Oberkörper vor die Station, greife beide Schlaufen mit den Händen und richte den Blick zur Säule. Deine Arme sind angewinkelt, die Hände berühren sich leicht – das sorgt für Kontrolle und Balance.","f":"Drücke deine Fäuste bzw. Unterarme langsam und kontrolliert nach unten, bis deine Arme fast vollständig gestreckt sind. Dabei bleiben die Oberarme dicht am Oberkörper, ohne sich zu bewegen.","t":"Knie möglichst nah an die Station – so behältst du die Spannung und vermeidest unnötigen Zug. Achte darauf, die Arme nicht ganz durchzustrecken, um die Ellenbogengelenke zu schonen.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"sumo-kreuzheben-deadlifts-mit-griffstange":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Griffstange auf halber Höhe deines Schienbeins befindet.","a":"Stelle dich mit breitem Stand in der Hockeposition hinter die Griffstange. Dein Schienbein sollte dabei fast die Griffstange berühren. Greife diese nun mit engem Obergriff. Achte darauf, dass dein Rücken leicht im Hohlkreuz ist, der Kopf die Verlängerung der Wirbelsäule bildet und der Blick nach vorne gerichtet ist. Halte deinen Rücken stets unter Spannung.","f":"Richte dich auf, während du die Arme gestreckt lässt. Die Kraft kommt aus deinen Beinen und der unteren Rückenmuskulatur. In der Endposition ziehst du die Schultern nach hinten, ohne sie zu heben.","t":"Die Belastung erfolgt bei dieser Übung nur über deine Beine und deinen unteren Rücken – Arme und Oberkörper werden nicht eingesetzt.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"rudern-seitlich-einarmig":{"v":"Du stellst den Schlitten so ein, dass er sich knapp unter der Brust in leicht geneigter Position befindet.","a":"Du platzierst deine Füsse hüftbreit, legst einen Unterarm stabil auf den Schlitten und greifst mit der anderen Hand das Horn vorne. Achte darauf, dass dein Schulterblatt abgesenkt ist und dein Körper voll angespannt bleibt.","f":"Ziehe den Kraftarm langsam seitlich zu den Rippen und lasse ihn danach kontrolliert in die Ausgangsposition zurückgleiten.","t":"Führe diese Übung stets in beide Bewegungsrichtungen aus.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"kickbacks-am-seilzug":{"v":"Hänge den Seilzug in unterer Position ein.","a":"Stell dich nah ans Gerät und stütz dich mit einer Hand an der Säule ab. Positioniere einen Fuss in der Schlaufe des Seilzugs.","f":"Streck den Fuss nach hinten aus und beuge den Oberkörper leicht nach vorne, sodass Bein und Rücken eine gerade Linie bilden. Das Standbein bleibt stabil und fast durchgestreckt.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Ausfallschritte","ausfallschritte"],["Einbeinige rückwärtige Beinpresse","einbeinige-rueckwaertige-beinpresse"],["Hüftheben","hueftheben"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"schulterdruecken-hinter-dem-kopf-mit-griffband":{"v":"Fixiere den Schlitten ganz unten und befestige das Griffband mit Hilfe des Karabinerhakens.","a":"Positioniere dich, mit hüftbreiter Beinstellung und dem Blick zur Wand, hinter das Griffband/die Griffstange. Greife nun die Griffstange weit aussen und halte den Rücken mit voller Spannung gerade.","f":"Drücke die Griffstange gleichmässig nach oben, bis deine Arme vollständig gestreckt sind. Senke sie dann langsam zurück in die Ausgangsposition. Noch bevor du den unteren Anschlag erreichst, drückst du sie jedoch wieder nach oben. Achte darauf, dass du während der gesamten Bewegung deine Rumpfmuskulatur angespannt hältst, damit du nicht ins Hohlkreuz fällst.","t":"Bei Bedarf kannst du das Griffband anpassen, indem du es mit einem oder mehreren Knoten verkürzt.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"],["Schulterdrücken mit engem Griff","schulterdruecken-mit-engem-griff"]]},
"hammer-curls":{"v":"Fixiere den Schlitten im unteren Bereich. Bringe anschliessen das Griffband an und lege die Griffstange in beide Griffschlauen ein.","a":"Stelle deine Füsse hüftbreit auf und halte deinen Oberkörper aufrecht und stabil. Lehne dich leicht zurück, ziehe die Schultern nach hinten und strecke die Brust nach vorne. Greife das Griffband unterhalb der Stange mit beiden Händen im Hammergriff und spanne deinen ganzen Körper an.","f":"Führe nun deine Arme gleichmässig, bis maximal nach oben. Bewege sie danach wieder langsam und gleichmässig zurück in die Ausgangsposition.","t":"Achte darauf, dass deine Ellbogen eng am Körper bleiben. Der Oberkörper sowie Schultern und Oberarme dürfen sich während der Übung nicht bewegen.","va":[["Bizepscurls stehend","bizepscurls"],["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"bizepscurls-mit-griffband":{"v":"Fixiere den Schlitten im oberen Bereich. Stelle danach die höchste Kraftstufe ein und ziehe das Griffband durch die Schlaufe.","a":"Greife mit jeder Hand eine Schlaufe des Griffbands. Lehne dich im 45°-Winkel mit Blick zur Wand nach hinten, bis das Band gespannt ist. Halte den Rücken gerade, spanne den Rumpf an und strecke die Beine nicht vollständig durch.","f":"Ziehe den Oberkörper kontrolliert nur mit dem Bizeps nach oben. Halte dabei die Spannung im ganzen Körper. Führe die Bewegung anschliessend langsam zurück in die Ausgangsposition.","t":"Achte darauf, die Bewegung ruhig und kontrolliert durchzuführen.","va":[["Bizepscurls stehend","bizepscurls"],["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend":{"v":"Fixiere die Schlitten auf Kniehöhe.","a":"Stell dich schulterbreit in eine leichte Hocke und beuge deinen Oberkörper etwa 45 Grad nach vorne, direkt zwischen die Schlitten. Greife jeweils ein Horn-Ende mit einer Hand. Halte deinen Rücken stets gerade und angespannt (leichtes Hohlkreuz), das Gesäss leicht nach hinten und die Brust leicht nach vorne herausgestreckt.","f":"Zieh beim Ausatmen eine Hand kontrolliert in Richtung Hüfte, halte die Position kurz und führe sie beim Einatmen langsam zurück in die Ausgangsposition. Wiederhole die Bewegung anschliessend mit der anderen Hand.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"201-vorgebeugtes-rudern-mit-griffstange":{"v":"Lege die Griffstange ein und fixiere den Schlitten auf Schienbeinhöhe.","a":"Stell dich schulterbreit hin, geh in eine leichte Hocke und beuge den Oberkörper etwa 45 Grad nach vorne. Positioniere dich hinter der Griffstange und greif sie im breiten Obergriff. Halte den Rücken unter voller Spannung gerade, das Gesäss leicht nach hinten und die Brust leicht nach vorne herausgestreckt. Der Blick geht Richtung Boden.","f":"Zieh die Griffstange beim Ausatmen in Richtung Hüfte, die Ellenbogen vom Oberkörper wegführend. Beim Einatmen führe die Stange langsam zurück in die Ausgangsposition.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"stehendes-wadenheben":{"v":"Platziere eine stabile Erhöhung direkt unterhalb der Griffstange, sodass du später mit deinen Fussballen darauf stehen kannst. Fixiere den Schlitten so, dass du die Stange mit gestreckten, hängenden Armen gerade noch bequem greifen kannst.","a":"Stelle dich hüftbreit vor die Station, blicke entspannt zur Wand und platziere deine Fuddballen mittig auf der Erhöhung, während deine Fersen maximal über die Kante hinausragen. Dein Oberkörper bleibt aufrecht, der Rücken gerade und die Spannung im Rumpf immer aktiv.","f":"Setze die Bewegung aus der Spannung deiner Wadenmuskulatur an und drücke dich kontrolliert über deine Fussballen nach oben, bis du maximal auf den Zehenspitzen stehst. Halte diesen Punkt kurz, um die Kontraktion zu maximieren. Dann lässt du deine Fersen langsam und gezielt wieder in die Ausgangsposition sinken.","t":"Nutze maximalen Hub in beide Richtungen – nach unten und nach oben –, um den gesamten Bewegungsumfang der Waden auszunutzen. Über eine höhere Unterlage kannst du die Bewegung intensivieren, da so der Bewegungsradius und die Stretchspannung steigen.","vt":"Wadenheben einbeinig oder sitzend mit Griffstange auf den Knien.","va":[["Wadenheben mit Griff am Horn","219-wadenheben-mit-griff-am-horn"],["Wadenheben sitzend","wadenheben-sitzend"],["Wadenheben stehend exzentrisch","wadenheben-stehend-exzentrisch"]]},
"brustdruecken-stehend":{"v":"Positioniere deinen Schlitten so, dass sich die  Griffstange auf Höhe deiner oberen Brust befindet. Achte darauf, dass sie möglichst hoch positioniert ist. So arbeitest du gezielt mit der Brustmuskulatur und verhinderst, dass die Bewegung aus einem zu stark nach vorne geneigten Oberkörper kommt.","a":"Nimm zum Start einen sicheren Stemmschritt ein. Lehn dich mit der Brust leicht an die Griffstange und neige den Oberkörper minimal nach vorne. Umfasse die Stange weit aussen im Obergriff. Achte bei dieser Übung immer auf einen geraden Rücken und einen angespannten Bauch.","f":"Bewege die Griffstange in einer gleichmässigen Bewegung nach unten, bis deine Arme gestreckt sind. Am tiefsten Punkt stoppst du kurz. Danach führst du die Stange langsam und kontrolliert zurück nach oben in die Ausgangsposition.","t":"Positioniere dich dicht an der Griffstange. Spanne deinen Rumpf fest an und bleibe während der gesamten Ausführung im Stemmschritt. Achte darauf, die Bewegung gezielt mit den Brustmuskeln zu führen – so trainierst du effektiv und sicher.","vt":"Bei dieser Übung kannst du mit der Griffbreite variieren. Je enger du greifst, desto höher ist die Belastung für deinen Trizeps. Je weiter du greifst desto stärker trainierst du deine Brustmuskulatur.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Butterfly","butterfly"],["Liegestütze mit Griffband","liegestuetze-mit-griffband"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"],["Liegestütze mit Griffband und Griffstange","liegestuetze-mit-griffband-und-griffstange"]]},
"207-latzug-alternierend-mit-griff-am-horn":{"v":"Fixiere den Schlitten auf Kopfhöhe. Die Enden der Hörner sind mit gestreckten Armen gerade noch erreichbar.","a":"Greife die Horn-Enden im Obergriff und stell dich so hin, dass dein Oberkörper leicht nach hinten geneigt ist.","f":"Zieh die Hände langsam und abwechselnd bis auf die Brust.","t":"Achte darauf, deine Ellbogen aktiv nach hinten zu führen und die Körperspannung während der gesamten Übungsausführung aufrechtzuerhalten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"beinstrecker-am-seilzug":{"v":"Hänge den Seilzug in mittlerer Position ein.","a":"Führ einen Fuss in die Schlaufe ein und winkel das Bein nach hinten an. Das andere Bein steht stabil. Halte den Oberkörper unter Spannung und aufrecht.","f":"Streck das angewinkelte Bein kontrolliert nach vorne. In der Endposition stehen beide Beine parallel zueinander. Achte darauf, dass das Knie immer neben dem Standbein bleibt.","t":"Führe diese Übung mit Sportschuhen aus, um einen sicheren Stand und eine bessere Druckverteilung der Seilzugschlaufe am Fuss zu gewährleisten.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Ausfallschritte","ausfallschritte"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Einbeinige Beinpresse","einbeinige-beinpresse"],["Beinpresse","beinpresse"],["Frontkniebeugen","kniebeugen"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"]]},
"beckenheben-liegend":{"v":"Stelle die höchste Kraftstufe ein. Fixiere den Schlitten etwas unterhalb der Säulenmitte und bringe das Griffband an.","a":"Lege dich auf den Rücken und positioniere deine Füsse in den Griffbandschlaufen. Die Beine sind gestreckt, mit leichtem Tonus. Deine Arme liegen entspannt neben dem Körper auf dem Boden.","f":"Drücke dein Becken nach oben in die Brettstellung, bis Oberkörper und Oberschenkel eine Linie bilden. Halte die Körperspannung und spanne die Gesässmuskulatur an. Senke das Becken langsam wieder ab, ohne den Boden zu berühren. Die Schultern und der Oberkörper bleiben entspannt.","t":"Halte deine Beine eng zusammen und parallel zueinander. In der Endposition etwas ausharren, ohne dabei ins Hohlkreuz zu fallen.","va":[["Hüftheben seitlich","hueftheben-seitlich"],["Hüftheben","hueftheben"]]},
"trizepsuebung-mit-langem-griffband":{"v":"Fixiere den Schlitten ganz unten und befestige das Griffband mit Hilfe des Karabinerhakens.","a":"Stelle dich hüftbreit hin, mit dem Rücken nahe am Horn. Greife das Griffband mit beiden Händen und strecke die Unterarme nach oben, sodass deine Oberarme direkt neben deinen Ohren bleiben. Halte deinen Oberkörper stabil, Rücken gerade und den Bauch angespannt.","f":"Drücke deine Unterarme langsam nach unten, ohne die Arme vollständig durchzustrecken. Die Ellenbogen und die Oberarme bewegen sich kaum. Führe die Bewegung danach kontrolliert zurück in die Ausgangsposition.","t":"Positioniere dich mit deinem Rücken zur Säule nahe am Horn.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"218-farmers-walk":{"v":"Fixiere die Schlitten auf Hüfthöhe, sodass sich die Hornspitzen etwa auf Mitte deiner Oberschenkel befinden. Dreh beide Schlitten leicht nach innen, damit der Zug durch die wippende Bewegung gleichmässig auf den Kolben wirkt.","a":"Stell dich im stabilen Stemmschritt hin. Greife mit jeder Hand ein Horn und geh in eine gestreckte Position. Halte den Rücken gerade, spanne den Bauch an und richte den Blick geradeaus.","f":"Verlagere dein Gewicht abwechselnd von einem Bein auf das andere und hebe dabei das unbelastete Bein leicht an. Wippe mit gestreckten Armen von einem Bein auf das andere hin und her, während die Arme immer gestreckt bleiben.","t":"Visualisiere, dass du zwei Eimer voller Sand in den Händen hältst, während du die Strecke zurücklegst – so bekommst du ein besseres Gefühl für die Belastung.","vt":"Führe die Übung am Anfang gerne nur in einer statischen Position durch, ohne das Wippen. So kannst du dich Schritt für Schritt an die Belastung gewöhnen.","va":[["Nackenheben hinten","nackenheben-hinten"]]},
"063-recrunch-mit-griffband":{"v":"Befestige das Griffband und stelle den Schlitten so ein, dass die Schlaufe sich in der knienden Ausgangsposition auf Höhe deines Kopfes befindet.","a":"Knie dich vor das Gerät und greife mit beiden Händen das hängende Griffband. Dein Oberkörper ist leicht nach vorne geneigt.","f":"Ziehe deine Ellbogen langsam in Richtung deiner Knie, wodurch sich dein Oberkörper aufrollt. Dabei bleibt die Position deiner Arme relativ zum Oberkörper konstant.","t":"Vor allem am Anfang, bis man den Bewegungsablauf beherrscht, sollte die Übung ganz langsam ausgeführt werden.","va":[["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Crunches","crunches"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"trizepsuebung-mit-griffband-2":{"v":"Stelle den Schlitten auf Brusthöhe in leichter Schräglage ein und befestige beide Griffbänder mit Hilfe des Karabinerhakens.","a":"Stelle dich im Ausfallschritt seitlich hin, sodass dein Rücken zum Gerät zeigt. Greife mit beiden Händen jeweils eine Schlaufe und halte deine Ellenbogen nahe am Kopf.","f":"Strecke deine Arme langsam nach unten aus, wobei deine Ellenbogen nahezu fixiert bleiben. Kehre anschliessend kontrolliert in die Ausgangsposition zurück.","t":"Achte darauf, dass die Bewegung nur aus dem Ellenbogen kommt – Schulter und Oberarm bleiben stabil.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"bizepscurls-mit-koerpergewicht":{"v":"Stelle die höchste Kraftstufe ein und lege die Griffstange ein. Fixiere den Schlitten so, dass sich die Griffstange unterhalb des Kinns befindet.","a":"Fasse nun die Griffstange etwas breiter als Schulterbreit und positioniere dich im 45°-Winkel mit Blick zur Wand.","f":"Beuge nun mit angespanntem Körper deine Arme und ziehe so dein Kinn über die Griffstange. Achtung: Dabei dreht sich die Griffstange in der Schlaufe.","vt":"Je tiefer du die Startposition wählst, desto anspruchsvoller wird diese Übung.","va":[["Bizepscurls stehend","bizepscurls"],["Hammer Curls","hammer-curls"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"055-haengendes-beinheben-mit-angewinkelten-beinen":{"v":"Den Blocker einlegen und die Griffstange durch die Schlaufe führen. Lege den Blocker ein und führe die Griffstange durch die vorgesehene Schlaufe.","a":"Fasse die Griffstange schulterbreit mit einem engen Obergriff. Spanne deine Bauchmuskeln an und halte deinen unteren Rücken gerade, ohne ins Hohlkreuz zu fallen.","f":"Ziehe deine Oberschenkel so weit wie möglich nach oben, indem du deine Hüfte beugst. Senke deine Beine anschliessend langsam und kontrolliert wieder in die Ausgangsposition ab.","t":"Tippe nach jeder Wiederholung deine Fussspitzen kurz auf den Boden. So stabilisierst du deinen Körper. Achte auch darauf, nicht mit Schwung zu arbeiten.","va":[["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"]]},
"schulterdruecken":{"v":"Positioniere deinen Schlitten so, dass sich die Griffstange auf Höhe deiner Oberbrust befindet.","a":"Nimm einen stabilen Stand ein und halte deinen Rücken gerade. Die Griffstange befindet sich auf Höhe deiner Oberbrust und deine Hände greifen die Griffstange weit aussen.","f":"Drücke die Griffstange gleichmässig nach oben, bis deine Arme vollständig gestreckt sind. Bewege sie danach langsam zurück – kurz bevor der untere Punkt (Ausgangsposition) erreicht ist, drückst du die Griffstange wieder nach oben.","t":"Achte darauf, immer eine stabile, gerade Haltung einzunehmen. Vermeide ein Hohlkreuz und halte deine Rumpfspannung konstant. Die Schultern nicht hochziehen und unten behalten.","vt":"Bei dieser Übung kannst du mit der Griffbreite variieren, um unterschiedliche Trainingsreize zu setzen. Weitere Varianten zum Schultertraining findest du weiter unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"]]},
"ausfallschritte-mit-griffband":{"v":"Stelle den Schlitten auf die höchste Kraftstufe ein und befestige das Griffband so, dass die Schlaufe unterhalb des Kniegelenks positioniert ist.","a":"Führe einen Fuss in die Schlaufe ein und winkle das Bein nach hinten an. Dein anderes Bein steht stabil am Boden. Die Oberschenkel stehen parallel zueinander. Dein Oberkörper bleibt stabil und aufrecht.","f":"Mache mit dem Bein, das sich in der Schlaufe befindet, einen grossen Schritt nach hinten. Das vordere Knie sollte einen 90-Grad-Winkel bilden, wobei das Knie über dem Knöchel bleibt. Das hintere Knie senkt sich fast bis zum Boden. Drücke dich dann mit dem vorderen Bein zurück in die Ausgangsposition. Wiederhole die Bewegung und wechsle dabei das Bein.","va":[["Ausfallschritte","ausfallschritte"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"072-schulterdruecken-hinter-dem-kopf":{"v":"Fixiere den Schlitten so, dass sich die Griffstange in sitzender Position auf deiner Nackenhöhe befindet.","a":"Du sitzt in der Ausgangsposition mit einem geraden Rücken und den Füssen auf dem Boden. Du greifst die Griffstange weit aussen.","f":"Drücke nun die Griffstange gleichmässig nach oben, bis deine Arme fast gestreckt sind. Dann bewegst du sie lansam wieder zurück in die Ausgangsposition. Bevor du den unteren Anschlag erreichst, drückst du die Griffstange wieder nach oben.","t":"Achte darauf, dass dein Körper stets stabil und aufrecht bleibt. Vermeide ein Hohlkreuz und halte die Spannung im Rumpf durchgehend aufrecht.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"]]},
"einbeiniges-kreuzheben":{"v":"Fixiere den Schlitten ganz unten und bringe das Griffband am Horn an.","a":"Stelle dich hüftbreit und mit Blick zur Wand hin. Fasse je eine Griffband-Schlaufe mit einer Hand und halte den rumpf stabil.","f":"Beuge die Hüfte und gehe mit geradem Rücken nach vorne, bis Kopf, Rücken und Bein eine horizontale Linie bilden. Halte dabei beide Beine gestreckt.","t":"Bei Bedarf kannst du die Hände durch die Schlaufe führen und das Griffband umwickeln. So verkürzt sich das Band und der Bewegungsumfang wird grösser.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"]]},
"schienbeinheben-sitzend":{"v":"Führe die Griffstange ein und fixiere den Schlitten ganz unten. Platziere eine stabile Erhöhung, wie ein Brett oder ein dickes Buch, auf dem Boden.","a":"Setze dich mit aufrechtem Oberkörper auf einen Ball oder Stuhl vor die Griffstange. Stelle deine Beine hüftbreit nebeneinander. Lege deine Fersen auf die Erhöhung und schiebe deine Zehen unter die Griffstange.","f":"Hebe deine Zehen langsam vom Boden ab und drücke sie so weit wie möglich nach oben. Bewege sie anschliesssend langsam wieder in die Ausgangsposition zurück.","va":[["Wadenheben mit Griff am Horn","219-wadenheben-mit-griff-am-horn"],["Stehendes Wadenheben","stehendes-wadenheben"],["Wadenheben sitzend","wadenheben-sitzend"],["Wadenheben stehend exzentrisch","wadenheben-stehend-exzentrisch"]]},
"205-rumaenisches-kreuzheben":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Stange ungefähr auf halber Schienbeinhöhe befindet.","a":"Stelle dich mit schulterbreitem Stand nah hinter die Stange. Greife sie ebenfalls schulterbreit im Obergriff. Beuge deine Beine leicht, während Oberkörper und Arme gestreckt bleiben. Halte den unteren Rücken stabil in einem leichten Hohlkreuz und richte den Blick nach vorne.","f":"Richte deinen Oberkörper kontrolliert über das Hüftgelenk auf, während deine Arme gestreckt bleiben. Halte den Kopf in Verlängerung der Wirbelsäule. Schiebe das Gesäss nach hinten und kehre dann langsam und kontrolliert in die Ausgangsposition zurück.","t":"Zum Einstieg kann der Schlitten höher eingestellt werden (etwa knapp unterhalb des Knies), damit du die Bewegung sicher erlernst. Mit zunehmender Sicherheit kannst du den Schlitten mit der Griffstange nach und nach tiefer fixieren.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"wadenheben-stehend-exzentrisch":{"v":"Fixiere den Schlitten so, dass sich die Griffstange auf Höhe deines Oberschenkels befindet. Platziere eine stabile Erhöhung (z.B. Brett o. dickes Buch) auf dem Boden.","a":"Stehe mit einer geschlossenen Beinstellung vor die Griffstange. Stehe mit den Fussballen auf die Erhöhung und gehe in die Dehnung der Wade.","f":"Greife die Griffstange im Untergriff mit gestreckten Armen. Drücke dann beide Beine aus den Waden nach oben. Anschliessend führe sie langsam zurück in die Ausgangsposition, wobei du abwechselnd ein Bein anwinkelst.","t":"Der Fokus dieser Übung liegt auf der exzentrischen Bewegung. Beim Hochdrücken setzt du beide Beine ein, um das Trainingsgewicht kontrolliert nach oben zu bewegen. Beim Absenken benutzt du nur ein Bein, um einen intensiveren Muskelreiz zu erzeugen.","va":[["Wadenheben mit Griff am Horn","219-wadenheben-mit-griff-am-horn"],["Stehendes Wadenheben","stehendes-wadenheben"],["Wadenheben sitzend","wadenheben-sitzend"]]},
"einarmiges-rudern-mit-obergriff-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Falte das Griffband zweimal und führ es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, beuge den Oberkörper leicht nach vorne und halte ihn stabil. Zieh die Schultern nach hinten und strecke die Brust heraus. Greif die Schlaufe einhändig im Obergriff.","f":"Zieh die Schlaufe kontrolliert zur Hüfte, während die Ellenbogen gerade nach hinten geführt werden. Drehe das Handgelenk während der Bewegung langsam in den Untergriff. Senke die Schlaufe danach langsam und gleichmässig wieder in die Ausgangsposition.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"unterarm-curls-hinter-dem-ruecken":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Griffstange unterhalb deines Gesässes befindet.","a":"Stelle dich hüftbreit mit dem Rücken nahe an die Griffstange. Fasse die Stange schulterbreit hinter deinem Körper. Spanne deine Bauchmuskeln an und halte deinen unteren Rücken gerade. Deine Arme sind nicht vollständig durchgestreckt.","f":"Beuge deine Handgelenke langsam so weit wie möglich. Kehre anschliessend kontrolliert in die Ausgangsposition zurück. Achte darauf, dass deine Arme während der gesamten Bewegung ruhig bleiben.","t":"Führe diese Übung langsam und ohne Schwung aus.","va":[["Unterarm-Curls mit Obergriff","unterarm-curls-mit-obergriff"]]},
"unterarm-curls-mit-obergriff":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass er sich auf Hüfthöhe befindet.","a":"Stelle dich hüftbreit vor die Griffstange, mit dem Blick gegen die Wand gerichtet. Fasse die Stange im Obergriff schulterbreit. Halte die Ellenbogen im 90°-Winkel nah am Oberkörper. Die Handgelenke sind nach vorne abgeknickt.","f":"Bewege die Handgelenke langsam nach oben, ohne die Oberarme zu verändern. Strecke die Handgelenke vollständig durch und senke sie anschliessend kontrolliert wieder in die Ausgangsposition ab.","t":"Führe die Übung langsam und ohne Schwung aus, um deine Muskulatur optimal zu aktivieren.","va":[["Unterarm-Curls hinter dem Rücken","unterarm-curls-hinter-dem-ruecken"]]},
"liegestuetze-mit-griffband-und-griffstange":{"v":"Fixiere den Schlitten im obersten Bereich und wähle die höchste Kraftstufe. Bring beide Griffbänder an und schiebe die Griffstange durch beide Schlaufen.","a":"Fasse die Griffstange mit gestreckten Armen. Lehne den Oberkörper leicht nach vorne und halte den ganzen Körper unter Spannung. Achte darauf, nicht ins Hohlkreuz zu fallen.","f":"Beuge die Arme und führe die Brust kontrolliert zwischen die Hände in Richtung der Griffstange. Die Stange bleibt dabei stabil. Senke anschliessend die Arme langsam zurück in die Ausgangsposition.","va":[["Liegestütze mit einem Bein im Griffband","liegestuetze-mit-einem-bein-im-griffband"],["Liegestütze mit Griffband","liegestuetze-mit-griffband"]]},
"rudern-mit-griffband":{"v":"Fixiere den Schlitten ganz unten, falte das Griffband und zieh es durch die Schlaufe.","a":"Mit schulterbreit gesetzten Füssen gehst du in eine leichte Kniebeuge und greifst die Schlaufen. Der Oberkörper neigt sich leicht nach vorne, während der Rücken stabil und gerade bleibt.","f":"Ziehe die Arme kontrolliert nach oben, während die Oberarme dicht am Körper bleiben. Achte darauf, Rücken und Hockeposition stabil zu halten. Anschliessend die Bewegung langsam und gleichmässig zurück in die Ausgangsposition führen.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"]]},
"215-kreuzheben-mit-griff-am-horn":{"v":"Fixiere die Schlitten so, dass sie sich auf Kniehöhe befinden.","a":"Stell dich hüftbreit in eine Hocke zwischen die Hörner. Richte deinen Blick vom Gerät weg und greife mit jeder Hand ein Horn-Ende. Halte den Rücken stets gerade und angespannt, leichtes Hohlkreuz erlaubt. Dein Kopf bleibt in Verlängerung der Wirbelsäule.","f":"Beim Aufrichten lassen die Arme immer gestreckt. Die Kraft kommt aus deinen Beinen und der unteren Rückenmuskulatur. In der Endposition sind die Schultern nach hinten gezogen, aber nicht angehoben.","t":"Achte darauf, dass die Kraft bei dieser Übung nur aus den Beinen und dem unteren Rücken kommt. Deine Arme und Schultern dienen lediglich der Stabilisierung.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"seitenheben-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Falte das Griffband zweimal und führe es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, halte den Oberkörper aufrecht und stabil. Steh seitlich zum Gerät und greif die Schlaufe mit der gegenüberliegenden Hand im Obergriff.","f":"Zieh die Schlaufe mit leicht angewinkeltem Arm kontrolliert nach oben, bis sie einen rechten Winkel zum Oberkörper bildet.","t":"Achte darauf, keine seitlichen Schwungbewegungen zu machen – die Ausführung bleibt kontrolliert und gerade.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Reverse Flys asymmetrisch am Seilzug","227-reverse-flys-asymmetrisch-am-seilzug"],["Reverse Flys vorgebeugt mit Seilzug","224-reverse-flys-vorgebeugt-mit-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"]]},
"trizepsdruecken-am-seilzug":{"v":"Hänge den Seilzug in oberer Position ein und führ die Griffstange durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, beuge den Oberkörper leicht nach vorne und halte ihn stabil. Zieh die Schultern nach hinten und strecke die Brust heraus. Greif die Griffstange mit beiden Händen schulterbreit im Obergriff und halte die Körperspannung voll aufrecht.","f":"Drück die Griffstange nach unten, während die Ellbogen an der gleichen Position bleiben. Bewege ausschliesslich die Unterarme.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"trizepsuebung-mit-griffband":{"v":"Fixiere den Schlitten so, dass die Griffbandschlaufen auf Brusthöhe positioniert sind.","a":"Stelle dich mit hüftbreitem Stand und aufrechtem, stabilem Oberkörper vor das Gerät. Greife mit beiden Händen die Schlaufen, sodass deine Hände sich berühren. Deine Arme sind angewinkelt, und dein Blick ist zur Säule gerichtet.","f":"Drücke die Fäuste /Unterarme langsam nach unten, bis deine Arme fast gestreckt sind. Achte darauf, dass deine Oberarme stabil und dicht am Oberkörper bleiben.","t":"Stehe nahe am Gerät und vermeide es, deine Arme vollständig durchzustrecken. So schonst du deine Ellenbogengelenke.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"einarmiges-trizepsdruecken":{"v":"Hänge den Seilzug in der oberen Position ein. Falte das Griffband zweimal und führe es durch die Schlaufe des Seilzugs.","a":"Stell dich stabil hin, lehne den Oberkörper leicht nach vorne und steh neben das Horn. Greif die Schlaufe mit einer Hand.","f":"Halte den Ellbogen nah am Oberkörper und strecke den Arm kontrolliert nach unten.","va":[["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"haengendes-beinheben-mit-gestreckten-beinen":{"v":"Du setzt den Blocker ein und führst die Griffstange durch die Schlaufe.","a":"Du greifst die Stange im breiten Obergriff und lässt deinen Körper frei hängen. Spanne deine Bauchmuskulatur an, halte den unteren Rücken gerade und vermeide ein Hohlkreuz. Deine Beine sind dabei relativ steif gehalten.","f":"Ziehe deine gestreckten Beine maximal nach oben.  Dein Oberkörper bleibt dabei nahezu unbewegt. Senke deine Beine danach kontrolliert zurück in die Ausgangsposition.","t":"Beginne zunächst mit einer leichteren Variante, zum Beispiel mit angezogenen Beinen oder einem engen Obergriff. Nach jeder Wiederholung kannst du mit den Fussspitzen kurz den Boden berühren, um deinen Körper zu stabilisieren. Vermeide bewusst jegliches Schwungholen.","va":[["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Rumpfrotation","rumpfrotation"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"bankdruecken-brustdruecken":{"v":"Du fixierst den Schlitten so, dass die Griffstange exakt auf deiner Brust aufliegt.","a":"Du legst dich auf Brusthöhe unter die Stange, greifst sie mit einem breiten griff, winkelst die Beine an und positionierst deine Füsse fest auf dem Boden.","f":"Du drückst die Stange gleichmässig nach oben, bis deine Arme fast gestreckt sind, und senkst sie anschliessend kontrolliert zurück in die Ausgangsposition.","t":"Du kannst den Kolben über die Gewichtsstufen herausbewegen, sodass sich das Horn leicht nach oben bewegt. Das ist ideal, um dich problemlos in die liegende Ausgangsposition zu bringen. Stelle das Gewicht erst ein, wenn du bereits in der liegenden Position bist.","vt":"Bei dieser Übung kann mit der Griffbreite variieret werden.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Fliegende mit Seilzug von unten","222-fliegende-mit-seilzug-von-unten"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Butterfly","butterfly"]]},
"adduktion-mit-griffband":{"v":"Du fixierst den Schlitten auf Schienbeinhöhe in leicht geneigter Position. Dann ziehst du das Griffband durch die Schlaufe.","a":"Du führst einen Fuss etwas angewinkelt in die Griffschlaufen ein und nimmst mit dem anderen Fuss einen stabilen Stand auf dem Boden ein. Achte darauf, dass der Abstand zum Horn so gross ist, dass das Band konstant unter Spannung steht. Halte deinen Oberkörper aufrecht, baue Körperspannung auf und richte deinen Blick zur Wand.","f":"Ziehe dein Bein in der Schlaufe langsam zur Mitte hin Richtung Standbein und führe es kontrolliert wieder zurück in die Ausgangsposition. Vermeide dabei jegliche Ausweichbewegung mit dem Oberkörper.","t":"Wenn du die Wand leicht berührst, findest du besseres Gleichgewicht. Achte darauf, die Übung stets auf beiden Seiten durchzuführen.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Adduktion am Seilzug","adduktion-am-seilzug"],["Abduktion am Seilzug","abduktion-am-seilzug"],["Rumpfrotation","rumpfrotation"],["Hüftheben seitlich","hueftheben-seitlich"],["Rumpfbeugen seitlich","rumpfbeugen-seitlich"]]},
"206-latzug-mit-griff-am-horn":{"v":"Fixiere den Schlitten auf Kopfhöhe. Die Enden der Hörner sind mit gestreckten Armen gerade noch erreichbar.","a":"Greife die Horn-Enden im Obergriff und stelle dich so hin, dass dein Oberkörper leicht nach hinten geneigt ist.","f":"Zieh die Hände langsam und gleichmässig bis neben die Brust.","t":"Achte darauf, die Ellbogen aktiv nach hinten zu bewegen und die Körperspannung die ganze Zeit über aufrechtzuerhalten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"liegestuetze-mit-einem-bein-im-griffband":{"v":"Stelle die höchste Kraftstufe ein. Fixiere den Schlitten in der oberen Hälfte und befestige das Griffband an einem Ende, sodass die Schlaufe etwa in der Mitte des Schienbeins positioniert ist. Lege einen Fuss in die Griffschlaufe und überkreuze das freie Bein über das andere.","a":"In der Stützposition bilden die Beine in Verlängerung der Wirbelsäule eine gerade Linie. Die Handgelenke befinden sich unter den Schultergelenken. Halte die Körperspannung aufrecht und vermeide ein Hohlkreuz. Der Blick ist zum Boden gerichtet.","f":"Senke deinen Körper kontrolliert nach unten. Achte darauf, die Spannung im Körper zu halten, sodass Beine, Oberkörper und Kopf eine Linie bilden. Die Ellenbogen zeigen dabei nach aussen. Senke dich so weit ab, bis deine Nase den Boden fast berührt, und drücke dich dann wieder nach oben.","t":"Bei den einzelnen Trainingssätzen, kannst du beim Einschlaufen die Beine abwechseln. Achte auf eine langsame und kontrollierte Übungsausführung.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Butterfly","butterfly"],["Liegestütze mit Griffband","liegestuetze-mit-griffband"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"]]},
"rumpfrotation":{"v":"Befestige das Griffband am Schlitten und fixiere diesen auf Höhe der Ellbogen und in einer waagrechten Position.","a":"Stelle dich seitlich zur Kraftstation, deine Füsse schulterbreit und fest am Boden. Baue eine Körperspannung auf und achte darauf, dass du einen stabilen Rücken haltest. Deine Arme sind nun angewinkelt und beide Hände greifen gleichzeitig beide Griffschlaufen.","f":"Führe die Hände kontrolliert in einer gleichmässigen Bewegung über deinen Körper und vorbei an der gegenüberliegenden Hüfte. Drehe dabei den Oberkörper bewusst mit, solange deine Füsse fest auf dem Boden bleiben. Spüre dabei, wie die Rotation aus der Rumpfmuskulatur kommt – deine Arme begleiten die Bewegung nur passiv.","t":"Nimm dir Zeit, um die richtige Position der Beine zu finden, damit du die Bewegung gut ausführen kannst. Nutze ausserdem bewusst die Rotation, ohne Schwung zu holen.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Rumpfbeugen seitlich","rumpfbeugen-seitlich"]]},
"ausfallschritte-nach-vorne":{"v":"Fixiere den Schlitten im unteren Bereich. Bringe anschliessend das Griffband an und lege die Griffstange in beide Schlaufen ein.","a":"Positioniere dich nun im Ausfallschritt über dem Horn. Halte in der tiefen Position die Griffstange vor deinem Schlüsselbein und drücke die Ellbogen nach vorne. Dein Blick ist dabei nach vorne gerichtet, dein Rücken bleibt gerade.","f":"Stehe mit Druck aus dem vorderen bein auf, sodass das Bein fast ganz gestreckt ist. Das Griffband wird eng am Körper geführt. Der Rücken blieibt gerade und angespannt.","va":[["Ausfallschritte","ausfallschritte"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"haengendes-beinheben-mit-angewinkelten-beinen":{"v":"Den Blocker einlegen und die Griffstange durch die Schlaufe führen. Lege den Blocker ein und führe die Griffstange durch die vorgesehene Schlaufe.","a":"Deine Hände greifen die Stange schulterbreit, sodass du dich sicher und kontrolliert frei halten kannst. Hänge dich nun aufrecht und mit engem Obergriff an die Stange, wobei deine Arme fast vollständig gestreckt sind. Deine Beine sind locker nach unten gelassen, der Oberkörper bleibt gerade, und du spannst bewusst deine Bauchmuskulatur an, damit der Rumpf stabil bleibt und du nicht in ein Hohlzreuz fällst.","f":"Ziehe deine Hüfte kontrolliert nach oben, bis deine Oberschenkel parallel zum Boden sind, während du die Knie in einem Winkel hältst. Halte einen Moment die Position, um die Spannung im Rumpf zu maximieren, und senke dann deine Beine langsam wieder ab in die Ausgangsposition. Tue dies ohne Schwung, aber mit bewusstem Muskelkontakt.","t":"Du kannst deine Fussspitzen nach jeder Wiederholung kurz am Boden antippen, um deinen Körper zu stabilisieren. Achte darauf, dass du die Übung nicht durch Schwungholen erleichterst.","va":[["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"]]},
"031-einbeinige-kniebeuge-am-horn":{"v":"Du stellst den Schlitten so ein, dass du das Horn mit leicht gebeugten Armen greifen kannst.","a":"Du stehst auf einem Bein und greifst das Horn. Spanne deine Arme an und halte sie während der gesamten Bewegung stabil.","f":"Du beugst das Standbein, senkst dein Gesäss kontrolliert ab und drückst dich anschliessend über Bein und Hüfte wieder in die aufrechte Ausgangsposition zurück.","t":"Wenn du die Bewegung gut beherrschst, senke die Kraftstufe. Dadurch erhöhst du die Schwierigkeit und intensivierst den Trainingsreiz.","va":[["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Frontkniebeugen","kniebeugen"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"227-reverse-flys-asymmetrisch-am-seilzug":{"v":"Hänge einen Seilzug in der oberen Position und den anderen in der unteren Position ein.","a":"Stelle dich in einer stabilen, leicht vorgebeugten Position vor die Kraftstation. Deine Füsse stehen parallel und schulterbreit. Greife nun die Schlaufen des Seilzugs überkreuzt mit jeder Hand.","f":"Führe deine Arme gestreckt seitlich nach hinten oben bzw. unten und richte dabei den Oberkörper leicht auf. Der Arm, der oben gestartet ist, bewegt sich nach unten, während der untere Arm nach oben zieht. Tausche danach die Schlittenposition und wiederhole die Bewegung für die andere Seite.","va":[["Reverse Flys vorgebeugt mit Seilzug","224-reverse-flys-vorgebeugt-mit-seilzug"]]},
"butterfly":{"v":"Fixiere den Schlitten im oberen Bereich, führe die Griffstange ein und befestige an beiden Enden je ein Griffband. Dabei wird die eine Schlaufe durch die andere geführt, sodass sich das Griffband um die Griffstange festzurrt und seitlich nicht wegrutschen kann.","a":"Mit dem Blick zum Gerät niederknien, den Oberkörper stabilisieren und nach vorne neigen. Die Position so wählen, dass sich die Griffstange Mitte Rücken befindet. Mit beiden Händen je ein Griffband fassen und in die Dehnung des Brustmuskels gehen. Knie dich mit dem Blick zum Gerät nieder, stabilisiere deinen Oberkörper und neige dich leicht nach vorne. Positioniere dich so, dass sich die Griffstange Mitte Rücken befindet. Greife mit beiden Händen je ein Griffband und gehe in die Dehnung des Brustmuskels.","f":"Führe deine Hände langsam und kontrolliert vor der Brust zusammen. Dein Oberkörper bleibt dabei stabil und unverändert.","t":"Das Fixieren der beiden Griffbänder kann anfangs etwas knifflig sein. Wenn du am Anfang zusätzliche Sicherheit möchtest, kannst du zwei kräftige Gummibänder aussen an der Griffstange anbringen. Achte darauf, die beiden Gummibänder straff festzuziehen, sodass sie nicht auf der Griffstange verrutschen. Mit etwas Erfahrung im Festzurren und in der Bewegungsausführung wirst du die Gummis schon bald nicht mehr benötigen.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Dips mit Gewicht","dips-mit-gewicht"]]},
"plank-to-pike":{"v":"Stelle die höchste Kraftstufe ein und befestige das Griffband, sodass die Schlaufe etwa am unteren Ende des Schienbeins positioniert ist. Lege ein Bein in die Griffschlaufe und überkreuze das freie Bein über das andere.","a":"In der Stützposition bilden die Beine in Verlängerung der Wirbelsäule eine gerade Linie. Die Handgelenke befinden sich unter den Schultergelenken. Halte die Körperspannung aufrecht und vermeide ein Hohlkreuz. Der Blick ist zum Boden gerichtet.","f":"Ziehe die Hüfte nach oben Richtung Decke, sodass dein Körper eine V‑Form bildet (Pike). Der Kraftimpuls geht hierbei auch vom Schultergürtel aus. Halte kurz die Position und senke die Hüfte kontrolliert zurück in die Ausgangsposition. Wiederhole die Bewegung langsam und kontrolliert.","t":"Beim Einschlaufen kannst du bei den einzelnen Trainingssätzen deine Füsse abwechseln.","va":[["Hüftheben seitlich","hueftheben-seitlich"],["Plank Jacks","plank-jacks"],["Unterarmstütz mit Griffband","unterarmstuetz-mit-griffband"]]},
"211-rudern-vorgebeugt-mit-griff-am-horn":{"v":"Fixiere den Schlitten auf Kniehöhe.","a":"Stell dich schulterbreit in eine leichte Hocke und beuge den Oberkörper etwa 45 Grad nach vorne, direkt zwischen die Schlitten. Greife jeweils ein Horn-Ende mit einer Hand. Halte deinen Rücken stets gerade und angespannt (leichtes Hohlkreuz), das Gesäss leicht nach hinten und die Brust leicht nach vorne herausgestreckt.","f":"Zieh beim Ausatmen die Hände kontrolliert in Richtung Hüfte. Beim Einatmen führst du die Hände langsam und gleichmässig zurück in die Ausgangsposition.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"bauchcrunches-seitlich":{"v":"Stelle die höchste Kraftstufe ein. Befestige das Griffband mit Hilfe des Karabinerhakens und stelle den Schlitten so ein, dass sich die Griffbandschlaufe Mitte Schienbein befindet.","a":"Knie dich in die Stützposition und hänge einen Fuss in die Griffbandschlaufe ein. Lege das andere Bein über das erste, sodass deine Beine eine gerade Linie in Verlängerung deiner Wirbelsäule bilden. Deine Handgelenke befinden sich unterhalb deiner Schultergelenke. Halte deinen Körper unter Spannung und achte darauf, nicht ins Hohlkreuz zu fallen. Dein Blick ist zum Boden gerichtet.","f":"Ziehe deine Knie seitlich so weit wie möglich nach vorne. Halte dabei deinen Bauch und Rücken unter Spannung und vermeide ein Hohlkreuz. Deine Schultern bleiben während der gesamten Bewegung stabil.","t":"Trainiere beide Seiten (links und rechts) alternierend.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Rumpfrotation","rumpfrotation"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Plank to pike","plank-to-pike"],["Crunches mit Griffband","crunches-mit-griffband"]]},
"202-frontkniebeugen":{"v":"Zieh die Griffstange durch die Schlaufe und stell den Schlitten so ein, dass die Stange in einer tiefen Hocke-Position leicht oberhalb der Brust liegt.","a":"Stell dich hüftbreit hin, Blick Richtung Wand. Greif das Horn etwas mehr als schulterbreit und drück die Ellenbogen nach vorne unter die Stange.","f":"Nutze die Beinkraft, um aufzustehen, und verlagere dabei den Schwerpunkt leicht nach vorne. Der Rücken bleibt gerade und unter Spannung.","t":"Nutze einen etwa 30 cm hohen Hocker. So kannst du bequem aus dem Sitzen unter die Griffstange gelangen.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"224-reverse-flys-vorgebeugt-mit-seilzug":{"v":"Hänge beide Seilzüge in der unteren Position ein.","a":"Stelle dich in einer stabilen, leicht vorgebeugten Position vor die Kraftstation. Deine Füsse stehen parallel und schulterbreit. Greife die Schlaufen des Seilzugs überkreuzt mit jeder Hand.","f":"Führe die Arme langsam und kontrolliert seitlich nach hinten oben, bis sie auf Schulterhöhe angekommen sind. Halte die Position kurz und aktiviere bewusst die Schultern. Anschliessend bringst du die Arme langsam und kontrolliert wieder zurück in die Ausgangsposition. Achte während der gesamten Übung auf einen stabilen Oberkörper und eine saubere, kontrollierte Ausführung.","va":[["Reverse Flys asymmetrisch am Seilzug","227-reverse-flys-asymmetrisch-am-seilzug"]]},
"bizepscurls":{"v":"Platziere den Schlitten im unteren Säulenbereich. Führe anschliessend das Griffband durch die Hornschlaufe und dann die Griffstange durch beide Griffbandschlaufen. Deine EISENHORN Kraftstation ist nun startklar für starke Bizepscurls.","a":"Beginne mit einer hüftbreiten Beinstellung und einem stabilen, aufrechten Oberkörper. Positioniere dich relativ nahe an der Säule bzw. über dem hinteren Bereich deines Horns. Zieh die Schulterblätter nach hinten unten und richte die Brust nach vorne oben auf. Greife jetzt die Griffstange im schulterbreiten Untergriff und baue volle Körperspannung auf.","f":"Für eine perfekte Bewegung führe die Griffstange kontrolliert mit der Kraft deiner Oberarme nach oben, bis du die maximale Beugung erreicht hast. Halte kurz die Spannung und bringe die Stange anschliessend langsam und gleichmässig wieder zurück in die Ausgangsposition.","t":"Achte darauf, deine Ellbogen eng am Körper zu halten. Oberkörper, Schultern und Oberarme bleiben stabil – die Bewegung erfolgt ausschließlich im Ellenbogengelenk. Sollte dir die Übung auf Kraftstufe 1 noch zu schwerfallen, starte zunächst mit den beiden Latzug-Varianten Latzug zur Brust oder Latzug in den Nacken , um deine Muskulatur vorzubereiten.","vt":"Wenn du die Griffstange im Obergriff fasst, aktivierst du neben dem Bizeps auch gezielt die Oberarmspeichenmuskeln.","va":[["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"trizepsuebung-mit-griffband-einarmig":{"v":"Fixiere den Schlitten ganz unten und bringe das Griffband mit einem Ende an der Schlaufe an.","a":"Stell dich hüftbreit rückwärts nahe ans Horn. Halte deinen Oberkörper aufrecht, mit leichtem Hohlkreuz, und ziehe die Schultern nach hinten. Spanne dabei die Bauchmuskeln an und greife das Griffband mit einer Hand.","f":"Führe den Unterarm kontrolliert nach oben, während der Oberarm dicht am Ohr bleibt. Achte darauf, dass sich Oberarm und Ellenbogen kaum bewegen. Strecke den Arm nicht vollständig durch, um den Ellenbogen zu schonen. Anschliessend den Unterarm langsam zurück in die Ausgangsposition führen.","t":"Denke daran, die Bewegung sowohl links als auch rechts zu trainieren, um beide Seiten gleichmässig zu belasten.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"]]},
"110-schulterdruecken-mit-engem-griff-sitzend":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass die Stange in sitzender Position auf Höhe des Schlüsselbeins liegt.","a":"Setz dich auf einen Ball oder Stuhl vor die Griffstange. Halte den Oberkörper aufrecht und stell die Beine hüftbreit auf den Boden. Greife die Griffstange schulterbreit.","f":"Drücke die Griffstange gleichmässig nach oben, bis die Arme gestreckt sind. Senke sie danach langsam wieder ab. Bevor die Stange den unteren Anschlag erreicht, leitest du die nächste Wiederholung ein.","t":"Achte auf eine aufrechte und stabile Körperhaltung. Vermeide ein Hohlkreuz, halte die Spannung im Rumpf stets aufrecht und lass deine Schultern unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"]]},
"bankdruecken-in-brueckenstellung":{"v":"Fixiere den Schlitten im unteren Bereich und lege die Griffstange ein. Stelle deine Beine hüftbreit auf den Boden und hebe das Gesäss an. Wähle die Höhe so, dass die Griffstange in der Brückenstellung auf deiner unteren Brust aufliegt.","a":"Leg dich so unter die Griffstange, dass sie auf Brusthöhe liegt, und greife sie an den Enden. Beuge die Ellenbogen, sodass sie sich auf Schulterhöhe befinden. Winkele die Beine an und stell die Füße fest auf den Boden. Halte dein Gesäss während der gesamten Übung angespannt.","f":"Drücke die Griffstange gleichmässig nach oben, bis die Arme fast gestreckt sind. Bewege dich anschliessend langsam wieder in die Ausgangsposition zurück.","t":"Achte darauf, dass dein Gesäss stets oben bleibt und nicht absinkt.","vt":"Du kannst die Intensität steuern, indem du die Griffbreite anpasst: Aussen greifen erleichtert die Übung, eng am Rohr macht sie anspruchsvoller.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"]]},
"hackenschmidt-kniebeuge":{"v":"Fixiere den Schlitten mittig und lege die Griffstange ein. Achte darauf, dass du die Höhe so einstellst, dass die Stange in tiefer Hocke genau auf deinem Nacken aufliegt.","a":"Gehe in eine tiefe Hocke und platziere die Griffstange sicher auf deinem Nacken. Stelle deine Füsse ungefähr eine Fusslänge vom Ende des Horns entfernt auf, damit du stabil stehst.","f":"Drücke dich nun kraftvoll aus der Hocke nach oben. Dein Körperschwerpunkt bewegt sich dabei leicht nach hinten oben. Achte darauf, am Ende der Bewegung deine Beine nicht komplett durchzustrecken. Halte den Rücken gerade, die Körperspannung fest und den Blick nach vorne gerichtet.","t":"Nutze einen tiefen Hocker, um bequem in die sitzende Startposition zu gelangen – so fällt dir der Einstieg deutlich leichter.","vt":"Die Fussposition kann etwas nach vorne oder zurück verschoben werden.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Frontkniebeugen","kniebeugen"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"recrunch-mit-griffband":{"v":"Befestige das Griffband an deiner Kraftstation und wähle die Schlittenhöhe so, dass die Schlaufen ungefähr auf Kopfhöhe hängen, wenn du dich davor positionierst.","a":"Greife das hängende Griffband mit beiden Händen und führe es zum Kopf. Deine Ellbogen bleiben nah am Kopf, während deine Beine leicht angewinkelt sind. Lehne dein Gesäss stabil gegen die Säule, sodass dein Körper fest verankert ist und du nicht ins Hohlkreuz fällst. Dein Rumpf ist aufgerichtet, die Bauchmuskulatur bereits leicht angespannt.","f":"Ziehe nun deine Ellbogen langsam in Richtung deiner angewinkelten Knie, während sich dein Oberkörper nach vorne zusammenrollt. Wichtig ist, dass die Bewegung nicht aus den Armen, sondern aus der Bauchmuskulatur initiiert wird – deine Arme bleiben in ihrer Position fixiert, und nur der Rumpf rollt sich aktiv ein. Achte darauf, die gesamte Bewegung ruhig, gleichmässig und ohne Schwung auszuführen.","t":"Vor allem am Anfang, bis man den Bewegungsablauf beherrscht, sollte die Übung ganz langsam ausgeführt werden. Gerade zu Beginn ist es sinnvoll, den Recrunch sehr langsam und mit voller Konzentration durchzuführen. So bekommst du ein Gefühl für den Bewegungsablauf und lernst, die Spannung in der Bauchmuskulatur gezielt aufzubauen. Versuche bewusst aus der Körpermitte zu arbeiten und nicht mit Armen oder Schwung nachzuhelfen.","va":[["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"plank-jacks":{"v":"Stelle die höchste Kraftstufe ein und befestige beide Griffbänder mit einem Ende an der Schlaufe des Horns. Wähle die Höhe so, dass dein Körper in der Plank-Position waagerecht ausgerichtet ist.","a":"Hänge je einen Fuss in die Schlinge und nimm die Plank Position ein. Deine Hände befinden sich dabei unterhalb der Schultern.","f":"Führe deine Beine gleichzeitig maximal nach aussen und führe sie dann wieder zurück.","va":[["Plank to pike","plank-to-pike"],["Mountain Climbers","mountain-climbers"],["Unterarmstütz mit Griffband","unterarmstuetz-mit-griffband"]]},
"flys-einarmig-am-seilzug":{"v":"Hänge den Seilzug in mittlerer Position ein. Falte das Griffband zweimal und führe es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin und halte den Oberkörper aufrecht und stabil. Steh seitlich zum Gerät und greif die Schlaufe so, dass der Brustmuskel bereits leicht unter Spannung ist.","f":"Führe den Arm kontrolliert vor die Brust. Achte darauf, den Arm nicht vollständig durchzustrecken.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Butterfly","butterfly"]]},
"dips-mit-griffband":{"v":"Stelle die höchste Kraftstufe ein. Fixiere den Schlitten ganz oben und befestige beide Griffbänder mit Hilfe des Karabinerhakens.","a":"Greife mit beiden Händen je eine Schlaufe. Deine Füsse sind dabei gestreckt und nach vorne positioniert.","f":"Strecke nun deine Arme langsam durch und bewege dich anschliessend langsam wieder in die Ausgangsposition zurück.","t":"Führe die Übung langsam aus. Halte Arme und Hände dabei ruhig.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Dips mit Gewicht","dips-mit-gewicht"]]},
"220-shrugs-alternierend-mit-griff-am-horn":{"v":"Fixiere die Schlitten auf Hüfthöhe, sodass die Hornspitzen etwa in der Mitte deiner Oberschenkel liegen. Dreh beide Schlitten leicht nach innen und stell dich mit dem Rücken zum Gerät.","a":"Stell dich stabil und parallel hin. Greife mit jeder Hand ein Horn und halte die Arme gestreckt. Bei aufrechtem Stand spürst du bereits Zug auf dem Horn. Halte den Rücken gerade und den Bauch angespannt.","f":"Zieh eine Schulter über die Nackenmuskulatur gleichzeitig nach oben und leicht nach hinten. Halte die Position kurz und kehre dann langsam in die Ausgangsposition zurück. Wiederhole die Bewegung auf der anderen Seite. Die Arme bleiben während der gesamten Übung gestreckt.","t":"Stell dir vor, du möchtest deine Schultern so weit wie möglich hinter die Ohren schieben – ruhig und kontrolliert.","vt":"Führe die Bewegung wahlweise synchron mit beiden Seiten aus – so trainierst du Körper und Koordination gleichermassen.","va":[["Shrugs mit Griff am Horn","221-shrugs-mit-griff-am-horn"],["Nackenheben hinten","nackenheben-hinten"]]},
"231-alternierendes-bankdruecken-mit-griff-am-horn":{"v":"Fixiere die Schlitten in der Höhe so, dass sich die Hornspitzen auf der Höhe der Brust befinden.","a":"Greife mit jeder Hand ein Ende des Horns. Die Ellenbogen liegen dabei auf dem Boden. Halte die Beine angewinkelt und platziere die Füße stabil auf dem Boden.","f":"Drücke nun einen Arm nach oben, bis er fast vollständig gestreckt ist. Senke ihn langsam wieder ab und wechsle anschliessend die Bewegung auf die andere Seite.","t":"Wenn du die Schlitten etwas nach innen stellst, führt dich die Bewegung beim Hochdrücken automatisch leicht zur Mitte.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"]]},
"einarmige-bizepscurls":{"v":"Fixiere den Schlitten gan unten und bringe das Griffband an.","a":"Stelle dich hüftbreit mit dem Rücken zur Wand über das Horn und greife mit einer Hand beide Schlaufen. Achte darauf, die Höhe so einzustellen, dass der Arm stets gestreckt bleibt und Spannung hält. Der freie Arm ist vor dem Bauch angewinkelt und liegt mit der Hand an der Innenseite des Oberarms an. Ziehe die Schultern nach hinten und strecke die Brust nach vorne.","f":"Führe den Arm kontrolliert nach oben, bis zur maximalen Position, ohne dass sich der Ellbogen dabei verschiebt. Anschliessend den Arm langsam und gleichmäßig zurück in die Ausgangsstellung bringen.","va":[["Bizepscurls stehend","bizepscurls"],["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Hammer Curls","hammer-curls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"],["Einarmige Bizepscurls am Seilzug","einarmige-bizepscurls-am-seilzug"]]},
"brustdruecken-seitlich":{"v":"Du fixierst den Schlitten waagerecht auf Brusthöhe.","a":"Du gehst in einen hüftbreiten Stemmschritt, stützt einen Unterarm stabil auf den Schlitten und greifst mit der anderen Hand seitlich deiner Brust das Horn. Dein Oberkörper ist leicht nach vorne geneigt, du baust gezielt Körperspannung auf.","f":"Jetzt drückst du das Horn kontrolliert nach vorne, der Ellbogen gleitet dabei horizontal. Anschliessend führst du die Bewegung langsam und bewusst zurück in die Ausgangsposition.","t":"Beende die Bewegung vor dem Anschlag und starte dann eine neue Wiederholung. Achte darauf, die Muskelspannung während der Übung konstant zu halten.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Explosives Brustdrücken am Horn alternierend","213-explosives-brustdruecken-am-horn-alternierend"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"],["Liegestütze mit Griffband und Griffstange","liegestuetze-mit-griffband-und-griffstange"]]},
"latzug-mit-griffband":{"v":"Stelle die höchste Kraftstufe ein und fixiere den Schlitten im oberen Bereich. Bringe anschliessend das Griffband am Horn an.","a":"Greife je eine Schlaufe des Griffbands mit einer Hand. Stelle dich mit geschlossenen Füssen auf den Boden und lehne dich mit gestreckten Armen nach hinten, bis das Band gespannt ist und dein Gesäss kurz über dem Boden schwebt.","f":"Ziehe deinen Körper nach oben, bis der Kopf auf Höhe der Hände ist. Öffne die Brust und ziehe die Schulterblätter aktiv nach hinten und unten. Führe die Bewegung anschliessend langsam zurück in die Ausgangsposition.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"]]},
"rudern-im-ausfallschritt-am-seilzug":{"v":"Hänge den Seilzug in der oberen Position ein. Falte das Griffband und führ es durch die Seilzug-Schlaufe.","a":"Stell dich im Ausfallschritt seitlich zum Gerät. Heb das hintere Knie leicht vom Boden ab. Greif die Griffbandschlaufen mit beiden Händen.","f":"Zieh die Hände kontrolliert vor die Brust, während du die Schulterblätter nach hinten zusammenziehst.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"111-latzug-in-den-nacken-sitzend":{"v":"Fixiere den Schlitten auf Kopfhöhe. In sitzender Position ist die Griffstange bei gestreckten Armen gerade noch erreichbar.","a":"Greif die Griffstange und setz dich so hin, dass der Oberkörper leicht nach vorne geneigt ist.","f":"Zieh die Griffstange langsam und gleichmässig bis auf den Nacken.","t":"Neige deinen Kopf sanft nach vorne, um die Griffstange sicher in den Nacken zu führen. Achte darauf, deine Körperspannung die ganze Zeit über aufrechtzuerhalten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"einbeiniges-kreuzheben-einarmig":{"v":"Fixiere den Schlitten im unteren Bereich und befestige das Griffband.","a":"Stelle dich mit Blick zur Wand und einem stabilen Stand vor das Gerät. Greife die Schlinge des Griffbandes mit einer Hand. Wenn nötig, wickele das Band einmal um deine Hand, um die Länge anzupassen.","f":"Beuge deine Hüfte und führe deinen Oberkörper nach vorne, während dein freies Bein gestreckt nach hinten ansteigt. Dein Kopf, Oberkörper und das angehobene Bein bilden eine gerade Linie. Achte darauf, deinen Rücken gerade zu halten und die Körperspannung aufrechtzuerhalten.","t":"Halte deinen Kopf während der Bewegungsausführung in einer neutralen Position.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"seitliche-crunches-am-seilzug":{"v":"Hänge den Seilzug in unterer Position ein.","a":"Leg dich mit den Füssen zum Gerät auf den Rücken. Dreh den Oberkörper leicht seitlich nach vorne und greif die Schlaufe mit einer Hand. Heb den Kopf leicht vom Boden ab.","f":"Spanne die Rumpfmuskulatur an und beweg den Oberkörper kontrolliert zur anderen Seite. Die freie Hand bleibt dabei gestreckt nach vorne.","t":"Achte darauf, die Bewegung sowohl links als auch rechts auszuführen, um beide Körperseiten gleichmässig zu trainieren.","va":[["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"rumpfbeugen-seitlich":{"v":"Fixiere den Schlitten ganz unten und leicht schräg. Bringe anschliessend das Griffband an.","a":"Stell dich hüftbreit mit dem Rücken zur Wand seitlich ans Horn und greife die Schlaufe mit einer Hand. Achte darauf, die Höhe so einzustellen, dass dein Arm die ganze Zeit gestreckt bleibt und unter Spannung steht.","f":"Richte den Oberkörper langsam auf und überstrecke ihn leicht. Gehe dann zurück in die Ausgangsposition.","t":"Achte darauf, die Übung sowohl rechts als auch links durchzuführen, um beide Körperseiten gleichmässig zu trainieren.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Rumpfrotation","rumpfrotation"]]},
"hueftheben-seitlich":{"v":"Du wählst die höchste Kraftstube und legst danach das Griffband ein. Die Schlaufe wird in etwa mittlerer Schienbein-Höhe positioniert.","a":"Du liegst auf der Seite, ein Unterarm stützt deinen Körper stabil ab. Du hängst nun deinen unteren Fuss in die Schlaufe ein, der andere liegt darauf. Dabei ist dein Körper, vom Fussgelenk über die Hüfte bis zum Kopf, in einer durchgehenden Linie. Baue Körperspannung auf und vermeide Schaukelbewegungen. Wähle die Position so, dass das Griffband leicht zum Gerät zeigt.","f":"Du hebst deine Hüfte kontrolliert an, bis dein gesamter Körper in einer seitlichen Plank-Position schwebt. Achte darauf, dass Fussgelenk, Hüfte und Kopf eine gerade Linie bilden. Die Körperspannkraft beibehalten und anschliessend die Hüfte langsam absenken.","t":"Übe zuerst nah am Boden und achte stets auf stabile Körperspannung. Je höher das Band oder je näher deine Füsse an der Säule sind, desto anspruchsvoller wird die Übung. Wiederhole die Übung immer auf beiden Seiten.","va":[["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Rumpfrotation","rumpfrotation"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"laufschritt-mit-griffband":{"v":"Lege die höchste Kraftstufe ein und bringe beide Griffbänder an.","a":"Lege dich auf den Rücken und führe beide Füsse je in eine Schlaufe ein.","f":"Heb das Becken vom Boden an, die Beine bleiben zunächst gestreckt. Die Arme liegen entlang des Körpers auf dem Boden. Spanne den Rumpf an und zieh abwechselnd die Fersen in Richtung Gesäss. Dabei bleibt das Becken oben.","va":[["Plank to pike","plank-to-pike"],["Mountain Climbers","mountain-climbers"],["Plank Jacks","plank-jacks"],["Unterarmstütz mit Griffband","unterarmstuetz-mit-griffband"]]},
"dips-mit-gewicht":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Griffstange etwas höher als dein Bauchnabel befindet.","a":"Stelle dich hüftbreit mit dem Rücken nahe an die Griffstange. Führe die Ellenbogen nach hinten und fasse die Griffstange mit einem breiten Griff. Halte die Schultern tief, spanne den Oberkörper und den Bauch an.","f":"Drücke die Griffstange gleichmässig nach unten, bis deine Arme gestreckt sind. Senke die Stange anschliessend kontrolliert und langsam wieder in die Ausgangsposition zurück.","t":"Achte darauf, möglichst nahe an der Griffstange zu stehen und stabil im Rumpf zu bleiben. Vermeide es, nach hinten auszuweichen oder die Schultern anzuheben.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Dips mit Griffband","dips-mit-griffband"]]},
"einarmiger-latzug-am-seilzug":{"v":"Hänge den Seilzug in oberer Position ein. Falte das Griffband und führ es durch die Schlaufe des Seilzugs.","a":"Setz dich mit angewinkelten Beinen auf den Boden. Greif mit einer Hand die Schlaufe und stütz die andere Hand auf dem Boden ab.","f":"Zieh die Hand seitlich am Oberkörper entlang und dreh sie dabei langsam ein, sodass die Handflächen am Ende nach oben zeigen. Halte den Oberkörper während der gesamten Bewegung stabil und ruhig.","va":[["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"203-kniebeugen":{"v":"Fixiere den Schlitten in der Mitte der Säule und lege die Griffstange ein.","a":"Stelle die Höhe so ein, dass die Stange in einer tiefen Hocke auf den Nacken gelegt werden kann. Die Füsse sind etwa eine Fusslänge vor dem Ende des Horns positioniert.","f":"Steh mithilfe der Beinkraft auf. Während der Aufwärtsbewegung verlagert sich der Schwerpunkt leicht nach hinten. Strecke die Beine am Ende der Bewegung nicht vollständig durch. Halte den Rücken gerade und unter Spannung. Der Blick geht gerade nach vorne.","t":"Verwende einen etwa 30 cm hohen Hocker. So kannst du bequem aus dem Sitzen unter die Griffstange gelangen.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"ueberkopf-ausfallschritte":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass die Griffstange am tiefsten Punkt der Ausfallschritt-Position gerade noch greifbar ist.","a":"Positioniere dich im Ausfallschritt unter der Griffstange. Greife die Griffstange weit aussen und strecke deine Arme unter Spannung nach oben. Achte darauf, dass sich die Griffstange über deinem Nacken befindet.","f":"Stehe mit Druck aus dem vorderen Bein auf, bis das Bein fast gestreckt ist. Dein Rücken bleibt unter Spannung und gerade.","t":"Achte darauf: Ein weiter Ausfallschritt trainiert die Gesässmuskulatur stärker, während die Oberschenkel etwas weniger belastet werden.","va":[["Ausfallschritte","ausfallschritte"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"stehendes-rudern-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Führ die Griffstange durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, beuge den Oberkörper leicht nach vorne und halte ihn stabil. Zieh die Schultern nach hinten und strecke die Brust heraus. Greif die Griffstange im Obergriff.","f":"Zieh die Griffstange kontrolliert zum Unterbauch, während die Ellenbogen gerade nach hinten geführt werden. Senke sie danach langsam und gleichmässig wieder in die Ausgangsposition.","va":[["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"066-trizepsuebung-mit-griffstange-kniend":{"v":"Befestige das Griffband und lege die Griffstange in beide Griffschlauen ein. Stelle die Höhe dabei so ein, dass sich die Griffstange in kniender Position leicht unter der Brust befindet.","a":"Knie dich vor das Gerät und greife die Griffstange im Obergriff. Dein Oberkörper ist leicht nach vorne geneigt, der Rücken gerade und die Bauchmuskeln angespannt.","f":"Drücke die Griffstange nach unten. Deine Ellbogen bleiben unverändert an der gleichen Position. Nur die Unterarme bewegen sich.","t":"Achte darauf, nah am Gerät zu knien. So verhinderst du, dass deine Ellbogen während der Bewegung nach vorne gezogen werden.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"213-explosives-brustdruecken-am-horn-alternierend":{"v":"Fixiere die Schlitten auf Hüfthöhe.","a":"Stell dich im stabilen Stemmschritt hin. Greife mit jeder Hand ein Horn, sodass dein Oberkörper leicht nach vorne geneigt ist. Halte den Rücken gerade, spanne den Bauch an und richte den Blick zum Boden. Gehe bereits in der Ausgangsposition in die Dehnung deiner Brust.","f":"Drücke eine Hand nach unten, bis der Arm vollständig gestreckt ist. Während du in die Ausgangsposition zurückkehrst, senkst du gleichzeitig die andere Hand nach unten und wiederholst die Bewegung abwechselnd. Achte dabei darauf, deinen Rumpf zu stabilisieren, damit dein Oberkörper möglichst ruhig bleibt.","t":"Achte darauf, den Oberkörper leicht nach vorne zu neigen und den Rumpf stabil zu halten. Im Stemmschritt führst du die Bewegung bewusst mit der Brustmuskulatur.","vt":"Die Übung kann auch kontrolliert und ohne explosive Bewegung ausgeführt werden, indem jeder Hub einzeln durchgeführt wird. Drücke eine Hand nach unten und bringe sie wieder zurück in die Ausgangsposition, bevor du die Bewegung mit der anderen Seite wiederholst.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Brustdruecken stehend mit Griffstange","209-brustdruecken-stehend-mit-griffstange"],["Bankdrücken (Brustdrücken)","bankdruecken-brustdruecken"],["Brustdrücken stehend","brustdruecken-stehend"],["Brustdrücken seitlich","brustdruecken-seitlich"],["Dips mit Gewicht","dips-mit-gewicht"],["Dips mit Griffband","dips-mit-griffband"]]},
"latzug-zur-brust":{"v":"Zum Start fixierst du den Schlitten auf Kopfhöhe. Greife anschliessend die Griffstange mit gestreckten Armen, sodass sie gerade noch erreichbar ist.","a":"Zum Start dieser Kraftübung stehst du aufrecht mit den Füssen schulterbreit auseinander. Die Griffstange greifst du jetzt im Obergriff und positionierst dich so, dass dein Oberkörper leicht nach hinten geneigt ist. Diese Ausgangsposition sorgt für Sicherheit und maximale Effektivität der Übung.","f":"Ziehe die Griffstange kontrolliert und gleichmässig nach unten, bis sie die Brust erreicht. Achte darauf, die Bewegung flüssig und nicht ruckartig auszuführen","t":"Konzentriere dich darauf, die Ellbogen nach hinten zu führen und deinen Körper während der gesamten Bewegung stabil und aufrecht zu halten. So erzielst du maximale Trainingswirkung.","vt":"Du kannst bei dieser Übung die Griffbreite variieren, um unterschiedliche Bereiche des Rückens intensiver zu trainieren. Alternativ lässt sich diese Kraftübung auch im Untergriff ausführen. Weitere Varianten zum Lat-Training findest du weiter unten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"russian-twist-am-seilzug":{"v":"Hänge den Seilzug in unterer Position ein.","a":"Setz dich mit aufrechtem Oberkörper vor das Gerät auf den Boden. Beuge die Beine leicht und stell die Füsse ab. Dreh den Oberkörper zum Gerät und greif die Schlaufe mit beiden Händen.","f":"Führe eine kontrollierte Oberkörperrotation durch und beweg die Schlaufe vor der Brust auf die andere Seite. Der Blick folgt den Händen. Anschliessend kehrst du wieder in die Ausgangsposition zurück.","t":"Achte darauf, die Bewegung sowohl links als auch rechts auszuführen, um beide Körperseiten gleichmässig zu trainieren.","vt":"Wenn du die Arme ganz ausstreckst, erhöhst du den Schwierigkeitsgrad der Übung deutlich.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Rumpfrotation","rumpfrotation"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Hüftheben seitlich","hueftheben-seitlich"],["Plank to pike","plank-to-pike"]]},
"nackenheben-hinten":{"v":"Fixiere den Schlitten im unteren Bereich der Säule. Befestige nun das Griffband und setze die Griffstange in beide Schlaufen des Griffbands ein.","a":"Stelle dich hüftbreit mit dem Rücken zum Gerät. Wähle die Höhe des Schlittens so, dass du die Griffstange in aufrechter Position mit gesenkten Schultern gerade noch erreichen kannst.","f":"Ziehe langsam deinen Nacken und deine Schultern zusammen, während du deine Arme entlang deines Körpers nach oben streckst. Senke anschliessend deine Schultern wieder langsam ab.","t":"Achte darauf, dass dein Kopf während der Übung ruhig bleibt und nicht nach vorne geschoben wird („Geierhals“ vermeiden).","va":[["Shrugs alternierend mit Griff am Horn","220-shrugs-alternierend-mit-griff-am-horn"],["Shrugs mit Griff am Horn","221-shrugs-mit-griff-am-horn"]]},
"kreuzheben-deadlifts-mit-gestreckten-beinen":{"v":"Lege die Griffstange ein und fixiere den Schlitten so, dass sich die Griffstange auf halber Höhe deines Schienbeins befindet.","a":"Stelle dich mit schulterbreitem Stand nahe hinter die Griffstange und fasse diese ebenfalls schulterbreit im Obergriff. Deine Beine sind nicht ganz durchgestreckt, der Oberkörper und die Arme hingegen schon. Dein unterer Rücken bildet ein leichtes Hohlkreuz, der Blick ist nach vorne gerichtet.","f":"Richte deinen durchgestreckten Oberkörper über das Hüftgelenk kontrolliert auf. Die Arme bleiben dabei immer gestreckt, dein Kopf bildet die Verlängerung der Wirbelsäule. Schiebe dein Gesäss nach hinten und senke dich langsam wieder in die Ausgangsposition ab.","t":"Um die Bewegung zu lernen, beginne mit einer höheren Schlittenposition (positioniere z. B. die Griffstange knapp unter deinen Knien). Sobald du die Technik beherrschst, kannst du den Schlitten schrittweise tiefer positionieren.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"aufrechtes-rudern-mit-breitem-griff":{"v":"Fixiere den Schlitten im untersten Bereich der Säule. Bringe das Griffband an und ziehe die Griffstange durch beide Griffschlaufen.","a":"Stelle dich mit hüftbreitem Stand und aufrechtem Oberkörper in die Mitte des Horns. Greife die Griffstange im schulterbreiten Obergriff und baue volle Körperspannung auf.","f":"Ziehe die Griffstange eng am Körper entlang, über die Ellenbogen, nach oben bis auf Schlüsselbeinhöhe. Am Endpunkt sollten deine Oberarme parallel zum Boden ausgerichtet sein.","t":"Schwinge bei dieser Übung nicht mit deinem Ober- oder Unterkörper. Eine gerade Halsstellung sorgt für Stabilität und schützt vor Verletzungen.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Shrugs alternierend mit Griff am Horn","220-shrugs-alternierend-mit-griff-am-horn"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Shrugs mit Griff am Horn","221-shrugs-mit-griff-am-horn"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Innenrotation mit Seilzug","innenrotation-mit-seilzug"],["Aussenrotation mit Seilzug","aussenrotation-mit-seilzug"],["Innenrotation seitlich mit Griffband","innenrotation-seitlich-mit-griffband"],["Aussenrotation seitlich mit Griffband","aussenrotation-seitlich-mit-griffband"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"]]},
"219-wadenheben-mit-griff-am-horn":{"v":"Fixiere die Schlitten auf Hüfthöhe, sodass die Hornspitzen etwa in der Mitte deiner Oberschenkel liegen. Dreh beide Schlitten leicht nach innen.","a":"Stell dich stabil und parallel hin. Greife mit jeder Hand ein Horn und halte die Arme gestreckt. Bei aufrechtem Stand spürst du bereits Zug auf dem Horn. Halte den Rücken gerade, den Bauch angespannt und den Blick geradeaus zur Wand gerichtet.","f":"Stehe nun leicht nach vorne auf deine Fussballen, soweit es geht. Die Arme bleiben dabei immer durchgestreckt. Achte darauf, dass deine Füsse parallel zueinander stehen. Stell dich nun so weit wie möglich auf deine Fussballen, die Arme bleiben dabei gestreckt. Achte darauf, dass deine Füsse parallel zueinander bleiben.","vt":"Stelle deinen Vorderfuss auf eine feste, rutschfeste Unterlage wie einen Holzklotz oder ein dickes Buch. So erreichst du eine noch tiefere Dehnung der Waden.","va":[["Stehendes Wadenheben","stehendes-wadenheben"],["Wadenheben sitzend","wadenheben-sitzend"],["Wadenheben stehend exzentrisch","wadenheben-stehend-exzentrisch"]]},
"beinbeuger-liegend":{"v":"Positioniere den Schlitten so, dass du deine Fersen bequem auf der Griffstange platzieren kannst. Lege die beiden Griffbänder über die Stange, um später sicheren Halt zu gewährleisten.","a":"So auf den Rücken liegen, dass das Gesäss direkt unter der Griffstange liegt. Die Füsse entspannt auf die Griffstange legen, sodass das Gesäss leicht vom Boden abgehoben ist. Lege dich auf deinen Rücken, so dass dein Gesäss direkt unter der Griffstange positioniert ist. Platziere die Füsse entspannt auf der Stange, sodass dein Gesäss leicht vom Boden abhebt.","f":"Spanne die Beinrückseite gezielt an und drücke die Stange nach unten, indem du die Knie in Richtung Brust ziehst. Ziehe dein Gesäss bewusst nach unten in Richtung Boden. Anschliessend lässt du die Stange langsam und kontrolliert wieder in die Ausgangsposition zurückkehren. Achte darauf, die Knie stabil zu halten – bei Bedarf kannst du die Bewegung durch Ziehen mit den Armen im Griffband unterstützen.","t":"Wenn du mit Stufe 1 startest und die Ausführung sicher beherrschst, erhöhst du die Kraftstufe nach und nach. So kannst du dich progressiv steigern, ohne deine Technik oder Kontrolle zu verlieren.","va":[["Beinbeuger mit Griffband","beinbeuger-mit-griffband"]]},
"schulterdruecken-sitzend-mit-angehobenen-fuessen":{"v":"Lege die Griffstange ein und setz dich mit geradem Rücken auf den Gymnastikball vor das Gerät. Stelle den Schlitten so ein, dass die Griffstange in sitzender Haltung direkt unterhalb deines Schlüsselbeins liegt.","a":"Fasse die Griffstange weit außen und hebe anschliessend beide Füsse vom Boden. Spanne deinen Rumpf an und halte den Oberkörper stabil, um die Balance zu sichern.","f":"Strecke die Arme langsam und kontrolliert nach oben, während Rücken und Rumpf stabil bleiben. Senke die Griffstange danach ebenso kontrolliert wieder in die Ausgangsposition zurück.","t":"Achte darauf, zentral auf dem Gymnastikball zu sitzen. Beginne mit einem niedrigen Gewicht, bis du die Bewegung sicher beherrschst.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"]]},
"crunches":{"v":"Stelle die höchste Kraftstufe an deiner Station ein und befestige das Griffband mittels mitgeliefertem Karabiner am Horn. Achte darauf, dass der Schlitten so fixiert ist, dass die andere Schlaufe beim Stütz knapp über deinem Ellenbogen endet.","a":"Stütze dich in einer Plank-ähnlichen Position ab, wobei du einen Fuss in die Schlaufe einhängst und das andere locker darüber legst. Deine Beine sollten eine Verlängerung der Wirbelsäule bilden, während die Handgelenke direkt unter den Schultergelenken positioniert sind. Halte deine Körperspannung und achte darauf, nicht ins Hohlkreuz zu fallen. Der Blick geht zum Boden.","f":"Ziehe deine Knie kontrolliert und so weit wie möglich in Richtung Brust, während du die Spannung in deinen Bauchmuskeln spürbar aktivierst. Die Schultern bleiben dabei stabil unter Spannung. Achte darauf, die Bewegung aus deiner Körpermitte heraus zu initiieren und nicht aus Schwung oder unkontrollierter Dynamik.","t":"Wechsle beim Einschlaufen die Beine ab, damit beide Seiten gleichmässig trainiert werden und du muskuläre Ausgleichsarbeit förderst.","vt":"Möchtest du die Übung anspruchsvoller gestalten, verändere einfach den Abstand zur Wand — je weiter weg du stehst, desto intensiver wird die Belastung auf deine Rumpfmuskulatur.","va":[["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"aufrechtes-rudern-mit-engem-griff":{"v":"Platziere den Schlitten im unteren Säulenbereich. Führe anschliessend das Griffband durch die Hornschlaufe und dann die Griffstange durch beide Griffbandschlaufen. Deine EISENHORN Kraftstation ist nun startklar.","a":"Beginne die Übung mit einem hüftbreiten Stand und geradem Oberkörper. Positioniere dich relativ nahe an der Säule bzw. über dem hinteren Bereich deines Horns. Die Griffstange wird eng im Obergriff gefasst. Baue volle Körperspannung auf, um eine sichere Ausgangsposition zu schaffen.","f":"Die Griffstange eng am Körper entlang nach oben bis unters Kinn ziehen. Am Endpunkt sind die Oberarme parallel zum Boden. Ziehe die Griffstange eng am Körper entlang nach oben, bis sie sich unterhalb deines Kinns befindet. Achte darauf, dass deine Oberarme am obersten Punkt parallel zum Boden ausgerichtet sind. Anschliessend senkst du deine Arme wieder kontrolliert in die Ausgangsposition ab.","t":"Die Bewegung erfolgt kontrolliert, ohne Schwung aus dem Unter- oder Oberkörper. Achte auf eine gerade Halsstellung und vermeide ein Überstrecken des Nackens („Geierhals“). Zu Beginn der Übung sind die Arme gestreckt. Das Griffband lässt sich bei Bedarf durch einen Knoten anpassen.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Reverse Flys asymmetrisch am Seilzug","227-reverse-flys-asymmetrisch-am-seilzug"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Reverse Flys vorgebeugt mit Seilzug","224-reverse-flys-vorgebeugt-mit-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"]]},
"094-trizepsuebung-mit-griffstange-untergriff-kniend":{"v":"Befestige das Griffband und lege die Griffstange in beide Schlaufen ein. Wähle die Schlittenhöhe so, dass die Stange in kniender Position auf Brusthöhe liegt.","a":"Greife die Griffstange im Untergriff. Lehne deinen Oberkörper leicht nach vorne, bleibe dabei nah an der Stange, halte den Rücken gerade und spanne die Bauchmuskeln an.","f":"Drücke die Griffstange nach unten. Deine Ellbogen bleiben dabei unverändert an der gleichen Position, nahe am Körper. Es bewegen sich nur deine Unterarme.","t":"Achte darauf, nahe am Gerät zu knien, um die Übung korrekt auszuführen.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"]]},
"rumpfrotation-am-seilzug":{"v":"Hänge den Seilzug in der oberen Position ein. Falte das Griffband zweimal und führe es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, halte den Oberkörper aufrecht und stehe diagonal zum Gerät. Dreh den Oberkörper leicht zum Gerät und greif die Griffschlaufe mit beiden Händen.","f":"Führe mit gestreckten Armen eine Rotation aus der Rumpfmuskulatur durch. Der Blick folgt den Händen. Das Bein, das nahe am Gerät steht, wird am Ende der Bewegung leicht eingedreht.","t":"Achte darauf, diese Übung in beide Richtungen auszuführen, um ein ausgewogenes Training zu erzielen.","va":[["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Rumpfrotation","rumpfrotation"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Hüftheben seitlich","hueftheben-seitlich"],["Hüftheben","hueftheben"],["Rumpfbeugen seitlich","rumpfbeugen-seitlich"]]},
"ausfallschritte-mit-griffstange":{"v":"Lege die Griffstange ein und fixiere den Schlitten ganz unten.","a":"Stelle dich mit hüftbreitem Schritt über die Griffstange. Positioniere dein vorderes Bein so, dass Ober- und Unterschenkel einen rechten Winkel bilden. Greife die Stange schulterbreit im Obergriff und richte deinen Blick nach vorne.","f":"Stehe nun mit Druck aus dem vorderen Bein auf, bis dieses fast ganz gestreckt ist. Der Rücken bleibt unter Spannung und gerade.","va":[["Ausfallschritte","ausfallschritte"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Stufe","ausfallschritte-mit-stufe"]]},
"adduktion-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein.","a":"Stell dich seitlich nah ans Gerät und positioniere den zugewandten Fuss in der Schlaufe. Das Standbein bleibt leicht gebeugt.","f":"Bewege das aktive Bein langsam und kontrolliert vor das Standbein, ohne die Hüfte zu drehen. Anschliessend das Bein wieder langsam nach aussen zum Gerät führen, ohne das Gewicht abzusetzen.","t":"Achte darauf, die Übung langsam und sauber auszuführen – vermeide Schwungbewegungen.","va":[["Kickbacks am Seilzug","kickbacks-am-seilzug"],["Abduktion am Seilzug","abduktion-am-seilzug"],["Adduktion mit Griffband","adduktion-mit-griffband"]]},
"232-schulterrotatoren-parallel-am-seilzug":{"v":"Hänge beide Seilzüge in der mittleren Position ein.","a":"Stelle dich aufrecht mit parallel ausgerichteten Füssen vor das Gerät. Greife die Schlaufen im Obergriff und beuge die Arme in Schulterhöhe. Achte darauf, dass deine Fäuste direkt auf die jeweiligen Säulen ausgerichtet sind.","f":"Führe deine Fäuste in einer bogenförmigen Bewegung nach hinten oben, bis sie etwa auf Kopfhöhe angekommen sind. Halte dabei den Oberarm so stabil wie möglich und achte darauf, dass die Bewegung ausschliesslich aus dem Unterarm über das Schultergelenk erfolgt.","va":[["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"]]},
"einbeinige-kniebeuge-mit-entlastung":{"v":"Befestige das Griffband so, dass die Schlaufen ungefähr auf Halshöhe hängen. Wähle bei der ersten Ausführung eine Kraftstufe, bei der du nahezu mit deinem gesamtes Körpergewicht am Griffband hängen kannst. So erhältst du optimale Unterstützung, bis du sicher genug bist, die Belastung selbstständig zu tragen.","a":"Stelle dich auf ein Bein und halte die Schlaufen des Griffbands mit beiden Händen fest. Deine Arme sind angespannt und bleiben stabil während der gesamten Bewegung.","f":"Beuge das Standbein langsam und senke dein Gesäss kontrolliert ab. Dann streckst du dein Bein und deine Hüfte kraftvoll, um dich wieder in die Ausgangsposition zurückzuführen. Die Bewegung erfolgt bewusst und ohne Schwung, wobei du die Muskulatur des gesamten Beins gleichmässig nutzt.","t":"Sobald du die Übung sicher beherrschst, reduziere die Kraftstufe stufenweise. Damit erhöhst du die Schwierigkeit und stärkst deine Muskulatur noch fokussierter.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Frontkniebeugen","kniebeugen"],["Einbeinige Kniebeugen seitlich","einbeinige-kniebeugen-seitlich"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"rudern-vorgebeugt-mit-obergriff":{"v":"Lege die Griffstange ein und fixiere den Schlitten auf Schienbeinhöhe.","a":"Stelle dich mit schulterbreitem Stand in leichter Hocke hinter die Griffstange. Die Griffstange mit breitem Oberergriff fassen. Beuge deinen Oberkörper etwa 45 Grad nach vorne, halte deinen Rücken mit voller Spannung gerade (leichtes Hohlkreuz). Schiebe dein Gesäss leicht nach hinten und strecke deine Brust leicht nach vorne heraus. Dein Blick ist zum Boden gerichtet.","f":"Ziehe die Griffstange beim Ausatmen in Richtung deiner Hüfte. Halte dabei die Ellenbogen so weit wie möglich vom Oberkörper entfernt. Führe die Griffstange während des Einatmens langsam zurück in die Ausgangsposition.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"facepulls-am-seilzug":{"v":"Hänge den Seilzug in oberer Position ein und führ das Griffband durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, stabil und leicht schräg zum Gerät. Greif mit beiden Händen eine Schlaufe des Griffbands. Wähle die Distanz zum Gerät so, dass bei aufrechter Haltung und gestreckten Armen bereits ein leichter Zug auf dem Seilzug spürbar ist.","f":"Zieh die Hände kontrolliert neben die Ohren. Halte in der Endposition die Oberarme im rechten Winkel zum Oberkörper und zieh die Schulterblätter nach unten.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"]]},
"216-rumaenisches-kreuzheben-mit-griff-am-horn":{"v":"Fixiere die Schlitten so, dass sich die Hörner ungefähr auf Höhe deiner Schienbeine befinden.","a":"Stell dich schulterbreit (nicht zu breit) zwischen die Hörner und greife sie jeweils mit einer Hand. Deine Beine sind leicht gebeugt, Oberkörper und Arme gestreckt. Dein unterer Rücken bildet ein leichtes Hohlkreuz, und dein Blick ist nach vorne gerichtet.","f":"Richte deinen Oberkörper über das Hüftgelenk kontrolliert auf. Die Arme bleiben immer gestreckt, der Kopf bildet die Verlängerung der Wirbelsäule. Schiebe das Gesäss zurück und kehre danach langsam in die Ausgangsposition zurück.","t":"Um die Bewegung zu erlernen, kann der Schlitten zunächst höher positioniert werden (z. B. unterhalb des Kniegelenks). Mit zunehmender Sicherheit lässt sich der Schlitten nach und nach tiefer einstellen.","va":[["Kreuzheben mit Griff am Horn","215-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"214-dips":{"v":"Stelle beide Schlitten etwas oberhalb deiner Hüfte ein. Wähle bei beiden Schlitten die höchste Stufe 12 oder lege alternativ beide Blocker ein.","a":"Stell dich zwischen die Schlitten, möglichst nah an die Wand. Greife mit beiden Händen den Rücken des Horns etwa auf Höhe der Gewichtsstufe 12. Lehne dich leicht nach vorne und überkreuze die Füsse in der Luft.","f":"Beuge deine Arme kontrolliert nach unten, bis du eine Dehnung im Trizeps und in der Brust spürst. Drücke dich dann langsam und kontrolliert wieder nach oben, sobald du den tiefsten Punkt erreicht hast. Halte während der gesamten Übung eine leichte Vorneigung und achte darauf, dass deine Handgelenke stabil bleiben.","t":"Du kannst die Übung auch aus einer haltenden Position starten und nur die negative (exzentrische) Bewegung nach unten ausführen. Am Ende erreichst du mit den Füssen den Boden und kehrst dann wieder in die Ausgangsposition zurück.","va":[["Dips mit Griffband tief","073-dips-mit-griffband-tief"],["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips mit Gewicht","dips-mit-gewicht"],["Dips mit Griffband","dips-mit-griffband"]]},
"aussenrotation-mit-seilzug":{"v":"Hänge den Seilzug in mittlerer Position ein.","a":"Stelle dich seitlich zum Gerät mit stabilem Stand hin. Halte deinen Oberarm nah am Körper und strecke den Unterarm im 90° Winkel nach vorne. Greife mit der äusseren Hand die Schlaufe und lege die andere Hand an die Hüfte.","f":"Führe den Unterarm langsam vom Bauch nach aussen. Der Ellenbogen bleibt dabei in Position. Kehre dann langsam zur Ausgangsposition zurück. Behalte stets die Spannung bei.","t":"Halte den Oberkörper stabil und unbewegt. Führe die Übung konsequent in beide Richtungen aus, um deine Muskulatur gleichmässig zu trainieren.","va":[["Aussenrotation seitlich mit Griffband","aussenrotation-seitlich-mit-griffband"]]},
"229-bankdruecken-mit-griffstange":{"v":"Fixiere die Schlitten in der Höhe so, dass die Griffstange auf deiner Brust aufliegt.","a":"Lege dich so unter die Griffstange, dass sie sich auf Brusthöhe befindet, und greife sie mit einem breiten Griff. Die Beine bleiben angewinkelt, die Füsse fest am Boden.","f":"Drücke die Griffstange gleichmässig nach oben, bis die Arme fast durchgestreckt sind. Senke sie anschliessend langsam und kontrolliert wieder zurück zur Brust.","t":"Vereinfache dir den Einstieg, indem du die Kolben zunächst über die eigentlichen Kraftstufen hinaus bewegst, sodass die Hörner nach oben rücken. Lege dich dann in die Position und stelle erst danach das gewünschten Gewicht ein.","vt":"Variiere die Griffbreite, um unterschiedliche Muskelbereiche gezielt zu trainieren.","va":[["Bankdrücken mit Griff am Horn","230-bankdruecken-mit-griff-am-horn"],["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"]]},
"228-klimmzug-mit-griffstange":{"v":"Lege die Griffstange ein und setze die Blocker ein. Stelle die Höhe so ein, dass du die Griffstange bei gestreckten Armen gerade noch erreichen kannst.","a":"Fasse die Griffstange mit breitem Obergriff. Deine Beine sind dabei entweder gerade ausgestreckt oder angewinkelt.","f":"Ziehe deinen Körper kontrolliert nach oben, bis dein Kinn die Höhe der Griffstange erreicht. Senke dich danach langsam und kontrolliert wieder zurück in die Ausgangsposition.","t":"Achte darauf, die Bewegung bewusst und ohne Schwung auszuüben, um die Muskulatur gezielt zu belasten.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug auf die Brust mit Griffstange","208-latzug-auf-die-brust-mit-griffstange"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug zur Brust","latzug-zur-brust"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"einbeinige-kniebeugen-seitlich":{"v":"Stelle die höchste Kraftstufe ein. Befestige das Griffband an einem Ende und justiere den Schlitten so, dass die Griffbandschlaufe mittig auf Höhe deines Schienbeins positioniert ist.","a":"Stelle dich seitlich zum Gerät und führe ein Bein in die Schlaufe ein. Das andere Bein bleibt stabil auf dem Boden. Lege deine Hände auf die Hüften und spanne deine Bauchmuskulatur an.","f":"Schiebe dein Gesäss so weit wie möglich nach hinten und beuge das Standbein, bis es einen 90°-Winkel erreicht. Kehre anschliessend langsam in die Ausgangsposition zurück.","t":"Achte besonders auf die Stellung deines Standbeins – sie ist ausschlaggebend. Je nach Beweglichkeit und Körperbau kann eine kleine Anpassung nötig sein.","va":[["Einbeinige Kniebeuge am Horn","031-einbeinige-kniebeuge-am-horn"],["Kniebeugen","203-kniebeugen"],["Frontkniebeugen","202-frontkniebeugen"],["Hackenschmidt Kniebeuge","hackenschmidt-kniebeuge"],["Einbeinige Kniebeuge mit Entlastung","einbeinige-kniebeuge-mit-entlastung"],["Frontkniebeugen","kniebeugen"],["Überkopf-Kniebeugen","ueberkopf-kniebeugen-overhead-squats"]]},
"unterarmstuetz-mit-griffband":{"v":"Fixiere den Schlitten im oberen Drittel. Stelle die höchste Kraftstufe ein und befestige das Griffband mit einem Ende an der Schlaufe.","a":"Hänge in der Plank-Position einen Fuss in die Schlaufe ein. Lege das andere Bein darüber, sodass beide Beine in Verlängerung der Wirbelsäule eine gerade Linie bilden. Achte darauf, dass deine Handgelenke direkt unter den Schultern liegen. Halte die Körperspannung und vermeide ein Hohlkreuz, während du den Blick zum Boden richtest.","f":"Bewege deinen Körper langsam nach hinten und vorne.","t":"Achte darauf, abwechselnd den linken und rechten Fuss in der Schlaufe zu platzieren und die Bewegung auf beiden Seiten durchzuführen.","va":[["Plank to pike","plank-to-pike"],["Mountain Climbers","mountain-climbers"],["Plank Jacks","plank-jacks"]]},
"einarmige-bizepscurls-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Falte das Griffband zweimal und führe es durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin und halte den Oberkörper aufrecht und stabil. Zieh die Schultern nach hinten und strecke die Brust nach vorne. Greife die Bandschlaufe mit einer Hand.","f":"Führe den Arm gleichmässig nach oben bis zur maximalen Höhe. Senke ihn danach langsam und kontrolliert wieder in die Ausgangsposition.","t":"Achte darauf, den Ellbogen stets nah am Körper zu halten. Dein Oberkörper, die Schultern und der Oberarm bleiben unbewegt, während nur der Ellbogen arbeitet.","va":[["Bizepscurls stehend","bizepscurls"],["Bizepscurls mit Körpergewicht","bizepscurls-mit-koerpergewicht"],["Hammer Curls","hammer-curls"],["Einarmige Bizepscurls","einarmige-bizepscurls"],["Bizepscurls mit Griffband","bizepscurls-mit-griffband"],["Bizepscurls mit Griffstange und Seilzug","bizepscurls-mit-griffstange-und-seilzug"]]},
"225-alterniederendes-rudern-vorgebeugt-mit-seilzug":{"v":"Hänge beide Seilzüge in der unteren Position ein.","a":"Stelle dich in einer stabilen, leicht vorgebeugten Position vor die Kraftstation. Deine Füsse stehen parallel und schulterbreit. Greife die Schlaufen des Seilzugs mit jeder Hand.","f":"Ziehe eine Hand langsam und kontrolliert in Richtung deiner Hüfte. Halte die Endposition kurz, bevor du die Hand wieder langsam zurück in die Ausgangsposition führst. Anschliessend wiederholst du die Bewegung mit der anderen Hand. Achte darauf, dass der Ellbogen während der gesamten Bewegung möglichst gerade nach hinten zeigt und die Hand am Ende leicht eingedreht wird.","t":"Stelle dir vor, du ziehst die Hand an die Hüfte – achte darauf, dass sie nicht zur Brust wandert.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"schulterdruecken-hinter-dem-kopf":{"v":"Fixiere den Schlitten so, dass die Griffstange auf Höhe des Nackens positioniert ist.","a":"Stelle dich mit hüftbreitem Stand und aufrechtem Oberkörper vor das Gerät. Greife die Griffstange weit aussen und baue volle Körperspannung auf.","f":"Drücke die Griffstange gleichmässig nach oben, bis deine Arme fast gestreckt sind. Senke sie dann langsam wieder ab, ohne den unteren Anschlag zu erreichen. Halte dabei stets die Spannung im Rumpfbereich aufrecht, um ein Hohlkreuz zu vermeiden.","t":"Achte bei dieser Übung darauf, deine Schultern während der Übung aktiv nach unten zu ziehen. So aktivierst du optimal deine Schultermuskulatur.","va":[["Facepulls am Seilzug","facepulls-am-seilzug"],["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Reverse Flys asymmetrisch am Seilzug","227-reverse-flys-asymmetrisch-am-seilzug"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Reverse Flys vorgebeugt mit Seilzug","224-reverse-flys-vorgebeugt-mit-seilzug"],["Schulterdrücken vor dem Kopf","200-schulterdruecken-vor-dem-kopf"],["Schulterdrücken vor dem Kopf","schulterdruecken"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"]]},
"crunches-mit-griffband":{"v":"Wähle die höchste Kraftstufe und befestige das Griffband so, dass die Schlaufe mittig auf Höhe deines Schienbeins positioniert ist.","a":"Blicke zum Gerät und hänge einen Fuss in die Schlaufe ein. Das freie Bein kannst du über das Andere legen. Deine Hände sind schulterbreit und fest auf dem Boden. Das Gesäss ist angehoben und die Beine sind gestreckt.","f":"Mit gestreckten Beinen ziehst du dein Gesäss langsam nach vorne und kehrst dann kontrolliert in die Ausgangsposition zurück.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"stehendes-rudern-mit-untergriff-am-seilzug":{"v":"Hänge den Seilzug in der unteren Position ein. Führ die Griffstange durch die Schlaufe des Seilzugs.","a":"Stell dich hüftbreit hin, beuge den Oberkörper leicht nach vorne und halte ihn stabil. Zieh die Schultern nach hinten und strecke die Brust heraus. Greif die Griffstange im Untergriff.","f":"Zieh die Griffstange kontrolliert zum Unterbauch, während die Ellenbogen gerade nach hinten geführt werden. Senke sie danach langsam und gleichmässig wieder in die Ausgangsposition.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"],["Aufrechtes Rudern mit breitem Griff","aufrechtes-rudern-mit-breitem-griff"]]},
"200-schulterdruecken-vor-dem-kopf":{"v":"Fixiere den Schlitten so, dass sich die Griffstange auf Höhe der Oberbrust befindet.","a":"Stell dich fest und parallel hin, halte den Rücken gerade und greif die Griffstange weit aussen.","f":"Drück die Griffstange gleichmässig nach oben, bis die Arme gestreckt sind. Senk sie danach langsam wieder ab, aber bevor der untere Anschlag erreicht ist, drück sie erneut nach oben.","t":"Achte während der gesamten Übung auf eine aufrechte und stabile Körperhaltung. Vermeide dabei ein Hohlkreuz, halte die Rumpfspannung und lass deine Schultern bewusst unten.","vt":"Passe die Griffbreite an – so kannst du die Intensität und den Fokus der Übung verändern.","va":[["Schulterdrücken hinter dem Kopf sitzend","072-schulterdruecken-hinter-dem-kopf"],["Schulterdrücken mit engem Griff sitzend","110-schulterdruecken-mit-engem-griff-sitzend"],["Schulterrotatoren parallel am Seilzug","232-schulterrotatoren-parallel-am-seilzug"],["Schulterdrücken am Horn alternierend","210-schulterdruecken-am-horn-alternierend"],["Schulterrotatoren alternierend am Seilzug","226-schulterrotatoren-alternierend-am-seilzug"],["Schulterdrücken hinter dem Kopf","schulterdruecken-hinter-dem-kopf"],["Schulterheben hinten","schulterheben-hinten"],["Schulterdrücken hinter dem Kopf mit Griffband","schulterdruecken-hinter-dem-kopf-mit-griffband"],["Schulterdrücken sitzend","schulterdruecken-sitzend"],["Schulterheben vorne","schulterheben-vorne"],["Schulterdrücken sitzend mit angehobenen Füssen","schulterdruecken-sitzend-mit-angehobenen-fuessen"],["Schulterdrücken mit engem Griff","schulterdruecken-mit-engem-griff"]]},
"073-dips-mit-griffband-tief":{"v":"Stelle für diese Übung die höchste Kraftstufe ein. Befestige beide Griffbänder mit Hilfe des Karabinerhakens.","a":"Greife mit beiden Händen je eine Schlaufe. Deine Füsse sind dabei gestreckt und nach vorne positioniert.","f":"Die Arme langsam beugen und anschliessend langsam wieder in die Ausgangsposition zurückbewegen. Beuge nun deine Arme langsam und bewege sie anschliessend wieder in die Ausgangsposition zurück.","t":"Achte darauf, die Bewegung in ruhigem Tempo ausführen. Halte deine Arme und deine Hände dabei stets stabil und ruhig.","va":[["Alternierende Dips stehend","217-alternierende-dips-stehend"],["Dips","214-dips"],["Dips mit Gewicht","dips-mit-gewicht"],["Dips mit Griffband","dips-mit-griffband"]]},
"204-kreuzheben":{"v":"Die Schlitten so fixieren, dass sich die Griffstange ungefähr auf Höhe der Schienbeinmitte befindet.","a":"Mit hüftbreitem Stand in eine Hockposition hinter die Griffstange gehen und diese im breiten Obergriff greifen. Der Blick ist etwa 45° zum Boden gerichtet. Den Rücken gerade und mit voller Spannung halten (leichtes Hohlkreuz). Kopf und Wirbelsäule bilden eine Linie.","f":"Die Bewegung über Beine und unteren Rücken einleiten, während die Arme gestreckt bleiben. Beim Aufrichten den Oberkörper stabil halten. In der Endposition die Schultern nach hinten ziehen, ohne sie anzuheben.","t":"Achte darauf: Die Kraft kommt bei dieser Übung ausschließlich aus den Beinen und dem unteren Rücken. Deine Arme und Schultern halten nur stabil.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Progressives Kreuzheben mit Griffband","progressives-kreuzheben-mit-griffband"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"mountain-climbers":{"v":"Stelle die höchste Kraftstunde ein und befestige das Griffband mit Hilfe des Karabinerhakens. Stelle den Schlitten nun so ein, dass sich die Griffbandschlaufen Mitte deines Schienbeins befinden.","a":"Hänge in der Stützposition je einen Fuss in eine Griffbandschlaufe ein. Halte deinen Körper gestreckt, sodass die Handgelenke direkt unter den Schultern liegen. Spanne den ganzen Körper an und achte darauf, nicht ins Hohlkreuz zu fallen. Richte deinen Blick nach unten.","f":"Ziehe deine Beine abwechselnd zum Oberkörper.","t":"Versuche, mit der Kniescheibe den Ellenbogen zu berühren. Führe die gesamte Bewegung dabei langsam und kontrolliert aus.","va":[["Rumpfrotation am Seilzug","rumpfrotation-am-seilzug"],["Crossover Crunch am Seilzug","crossover-crunch-am-seilzug"],["Russian Twist am Seilzug","russian-twist-am-seilzug"],["Seitliche Crunches am Seilzug","seitliche-crunches-am-seilzug"],["Hängendes Beinheben mit angewinkelten Beinen","055-haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","063-recrunch-mit-griffband"],["Crunches","crunches"],["Hängendes Beinheben","haengendes-beinheben-mit-angewinkelten-beinen"],["Recrunch mit Griffband","recrunch-mit-griffband"],["Hängendes Beinheben mit gestreckten Beinen","haengendes-beinheben-mit-gestreckten-beinen"],["Crunches mit Griffband","crunches-mit-griffband"],["Bauchcrunches seitlich","bauchcrunches-seitlich"]]},
"208-latzug-auf-die-brust-mit-griffstange":{"v":"Fixiere den Schlitten auf Kopfhöhe. Die Griffstange sollte mit gestreckten Armen gerade noch erreichbar sein.","a":"Greife die Griffstange im Obergriff und stell dich so hin, dass dein Oberkörper leicht nach hinten geneigt ist.","f":"Zieh die Griffstange langsam und gleichmässig bis auf die Brust.","t":"Achte darauf, die Ellbogen nach hinten zu führen und die Körperspannung während der gesamten Übung aufrechtzuerhalten.","vt":"Du kannst bei dieser Übung die Griffbreite variieren. Ausserdem lässt sie sich auch im Untergriff ausführen.","va":[["Einarmiger Latzug am Seilzug","einarmiger-latzug-am-seilzug"],["Latzug in den Nacken sitzend","111-latzug-in-den-nacken-sitzend"],["Latzug zur Brust sitzend","115-latzug-zur-brust-sitzend"],["Latzug alternierend mit Griff am Horn","207-latzug-alternierend-mit-griff-am-horn"],["Latzug mit Griff am Horn","206-latzug-mit-griff-am-horn"],["Latzug in den Nacken","latzug-in-den-nacken"],["Latzug mit Griffband","latzug-mit-griffband"]]},
"223-ueberkopf-trizeps-extensions-mit-seilzug":{"v":"Hänge beide Seilzüge in der unteren Position ein.","a":"Stell dich dem Gerät zugewandt hin und greife mit jeder Hand eine Seilzugschlaufe. Dreh dich anschliessend so, dass dein Rücken zum Gerät zeigt, und nimm eine stabile Position ein, indem du die Hände hinter dem Kopf überkreuz hältst und einen festen Stemmschritt einsetzt.","f":"Drücke nun deine Hände mit der Kraft deines Trizeps nach oben zur Decke. Achte dabei auf einen stabilen Rumpf und festen Stand. Kehre anschliessend kontrolliert in die Ausgangsposition zurück und spüre die Dehnung im Trizeps.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"],["Trizepsübung mit Griffband einarmig","trizepsuebung-mit-griffband-einarmig"],["Trizepsübung mit Griffstange Untergriff","trizepsuebung-mit-griffstange-im-untergriff"]]},
"trizepsuebung-mit-griffband-einarmig-2":{"v":"Fixiere den Schlitten im unteren Bereich und bringe das Griffband an einem Ende der Schlaufe an.","a":"Stelle dich seitlich mit hüftbreitem Stand nah ans Horn. Ziehe die Schultern zurück, halte den Oberkörper aufrecht und wölbe den unteren Rücken leicht ins Hohlkreuz. Spanne die Bauchmuskeln an und greife das Griffband mit einer Hand.","f":"Führe den Unterarm kontrolliert nach oben, während der Oberarm dicht neben den Ohren bleibt. Achte darauf, dass sich Oberarm und Ellenbogen kaum bewegen. Strecke den Arm nicht vollständig durch, um den Ellenbogen zu schonen. Anschliessend den Unterarm langsam zurück in die Ausgangsposition führen.","t":"Achte darauf, die Bewegung sowohl rechts als auch links durchzuführen, um beide Seiten gleichmässig zu trainieren.","va":[["Einarmiges Trizepsdrücken","einarmiges-trizepsdruecken"],["Trizepsdrücken am Seilzug","trizepsdruecken-am-seilzug"],["Überkopf-Trizepsdrücken am Seilzug","ueberkopf-trizepsdruecken-am-seilzug"],["Trizepsübung mit Griffband kniend","011-trizepsuebung-mit-griffband-kniend"],["Trizepsübung mit Griffstange Untergriff kniend","094-trizepsuebung-mit-griffstange-untergriff-kniend"],["Trizepsübung mit Griffstange kniend","066-trizepsuebung-mit-griffstange-kniend"],["Überkopf-Trizeps-Extensions mit Seilzug","223-ueberkopf-trizeps-extensions-mit-seilzug"],["Trizepsübung mit Griffstange","uebungen-fuer-den-trizeps"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-langem-griffband"],["Trizepsübung mit Griffband","trizepsuebung-mit-griffband-2"],["Trizepsdrücken","trizepsdruecken"]]},
"rudern-einarmig":{"v":"Fixiere den Schlitten so, dass sich das Horn ungefähr Mitte Schienbein befindet.","a":"Stehe in einem kleinen Ausfallschritt neben dem Gerät und fasse mit einer Hand das Horn an. Dein Rücken bleibt dabei gerade.","f":"Ziehe das Horn nun seitlich zur Hüfte und halte den Oberarm dabei eng am Oberkörper. Anschliessend bewegst du dich langsam wieder in die Ausgangsposition zurück.","t":"Die Übung unbedingt auf beiden Seiten ausführen.","va":[["Stehendes Rudern am Seilzug","stehendes-rudern-am-seilzug"],["Stehendes Rudern mit Untergriff am Seilzug","stehendes-rudern-mit-untergriff-am-seilzug"],["Einarmiges Rudern mit Obergriff am Seilzug","einarmiges-rudern-mit-obergriff-am-seilzug"],["Rudern im Ausfallschritt am Seilzug","rudern-im-ausfallschritt-am-seilzug"],["Vorgebeugtes Rudern mit Griffstange","201-vorgebeugtes-rudern-mit-griffstange"],["Rudern vorgebeugt mit Griff am Horn","211-rudern-vorgebeugt-mit-griff-am-horn"],["vorgebeugtes Rudern mit Griff am Horn alternierend","212-vorgebeugtes-rudern-mit-griff-am-horn-alternierend"],["Alternierendes Rudern vorgebeugt mit Seilzug","225-alterniederendes-rudern-vorgebeugt-mit-seilzug"],["Aufrechtes Rudern mit engem Griff","aufrechtes-rudern-mit-engem-griff"],["Rudern vorgebeugt mit Untergriff","rudern-vorgebeugt-mit-untergriff"],["Rudern seitlich einarmig","rudern-seitlich-einarmig"],["Rudern vorgebeugt mit Obergriff","rudern-vorgebeugt-mit-obergriff"]]},
"progressives-kreuzheben-mit-griffband":{"v":"Du fixierst den Schlitten ganz unten und faltest das Griffband zweimal. Dann ziehst du es durch die dafür vorgesehene Schlaufe.","a":"Du stellst dich hüftbreit auf, blickst zur Wand und gehst in die Knie. Dann fasst du die Schlingen mit beiden Händen. Achte darauf, dass dein Kopf mit der Wirbelsäule ausgerichtet ist und dein Rücken unter voller Spannung stabil und gerade bleibt.","f":"Du richtest dich langsam auf, indem du Kraft aus deinen Beinen und der unteren Rückenmuskulatur aufbaust. Dabei bleiben deine Arme stets gestreckt. Anschliessend bringst du deinen Körper kontrolliert zurück in die Ausgangsposition.","t":"Wenn du die Übung mit dem Blick zum Gerät ausführst, entsteht gegen Ende der Bewegung deutlich mehr Widerstand. So setzt du einen besonders effektiven Muskelreiz.","va":[["Rumänisches Kreuzheben mit Griff am Horn","216-rumaenisches-kreuzheben-mit-griff-am-horn"],["Rumänisches Kreuzheben","205-rumaenisches-kreuzheben"],["Kreuzheben","204-kreuzheben"],["Kreuzheben mit Griffstange","kreuzheben-mit-griffstange-deadlift"],["Einbeiniges Kreuzheben einarmig","einbeiniges-kreuzheben-einarmig"],["Sumo-Kreuzheben (Deadlifts) mit Griffstange","sumo-kreuzheben-deadlifts-mit-griffstange"],["Rumänisches Kreuzheben","kreuzheben-deadlifts-mit-gestreckten-beinen"],["Einbeiniges Kreuzheben","einbeiniges-kreuzheben"]]},
"ausfallschritte-mit-stufe":{"v":"Befestige das Griffband am Horn und schiebe die Griffstange durch beide Griffschlaufen. Fixiere den Schlitten ganz unten und stelle eine stabile Erhöhung vor das Gerät.","a":"Greife die Stange schulterbreit und platziere deinen vorderen Fuss fest auf der Erhöhung. Achte darauf, dass der Schlitten so eingestellt ist, dass in der tiefen Lunge-Position bereits leichter Zug auf der Stange liegt.","f":"Drücke dich kraftvoll über das vordere Bein nach oben, bis es fast gestreckt ist. Halte den Rücken dabei aufrecht und angespannt. Die Stange bleibt nah am Körper geführt.","va":[["Ausfallschritte","ausfallschritte"],["Ausfallschritte mit Griffband","ausfallschritte-mit-griffband"],["Überkopf-Ausfallschritte","ueberkopf-ausfallschritte"],["Ausfallschritte nach vorne","ausfallschritte-nach-vorne"],["Ausfallschritte mit Griffstange","ausfallschritte-mit-griffstange"]]},
"innenrotation-mit-seilzug":{"v":"Du hängst den Seilzug in der mittleren Position ein.","a":"Du stehst seitlich am Gerät in einem stabilen Stand. Dein Oberarm liegt eng am Körper, während du den Unterarm im 90° Winkel nach vorne streckst. Mit der inneren Hand greifst du die Schlaufe, die andere Hand legst du sicher auf deine Hüfte.","f":"Nun drehst du den Unterarm kontrolliert nach innen – die Bewegung kommt aus deiner Schulter, der Oberarm bleibt dabei stabil am Körper. Zieh die Schlaufe langsam zur Mitte vor deinen Bauch und führ sie dann ebenso kontrolliert wieder zurück. Die Spannung bleibt während der gesamten Übung bestehen.","t":"Halte den Oberkörper stabil und unbewegt. Führe die Übung konsequent in beide Richtungen aus.","va":[["Innenrotation seitlich mit Griffband","innenrotation-seitlich-mit-griffband"]]},
"230-bankdruecken-mit-griff-am-horn":{"v":"Fixiere die Schlitten in der Höhe so, dass sich die Hornspitzen auf der Höhe der Brust befinden.","a":"Greife mit jeder Hand das Ende eines Horns. Achte darauf, dass deine Ellenbogen auf dem Boden aufliegen. Die Beine bleiben angewinkelt, während die Füße stabil und fest auf dem Boden stehen.","f":"Drücke die Hände gleichmässig nach oben, bis deine Arme fast vollständig gestreckt sind. Senke sie danach kontrolliert zurück in die Ausgangsposition.","t":"Du kannst die Schlitten etwas nach innen eindrehen. So bewegen sich deine Arme beim Hochdrücken automatisch leicht zur Mitte, was die Ausführung erleichtert.","va":[["Alternierendes Bankdrücken mit Griff am Horn","231-alternierendes-bankdruecken-mit-griff-am-horn"],["Bankdrücken mit Griffstange","229-bankdruecken-mit-griffstange"],["Negativ Bankdrücken mit angehobenen Beinen","negativ-bankdruecken-mit-angehobenen-beinen"],["Bankdrücken in Brückenstellung","bankdruecken-in-brueckenstellung"]]}
};

